#!/usr/bin/env python3
"""The live round's driver (plan.md step 3; inputs#I3 for its pty host).

  live-hold.py rehearse-verify | live-verify        viola verify --record on a fresh home
  live-hold.py rehearse-wrapped | live-wrapped      one wrapped start: readings, refusals, keys, hold, killed wrapper
  live-hold.py rehearse-unwrapped | live-unwrapped  one unwrapped start: the status-line reading, a Ctrl-C stop

Each prints ONE closing line `{subcommand}: green|red|unread — {codes}` (exit 0 green, 1 red or unread, 3 refused)
and nothing that holds a path, prompt, assistant text, id or pid. A `live-*` subcommand reads founder-words.md
first and refuses (`refused: word {fork} unanswered`, nothing made or started) on a line it needs; a `rehearse-*`
one reads no founder line and drives the fake agent, both the granted and the refused key arm.

Its sessions run on a pty it opens itself in live-pty.py's form (size, declared environment, the Ctrl-C stop);
it adds only the key writes a founder line grants and an in-memory scan of the drained bytes, of which it keeps
counts alone. Every spawn has a kill deadline. Run from the repository root.
"""
import datetime
import errno
import hashlib
import importlib.util
import json
import os
import pathlib
import re
import select
import shutil
import signal
import subprocess
import sys
import termios
import time

EVID = pathlib.Path(__file__).resolve().parent
sys.dont_write_bytecode = True


def load(name):
    spec = importlib.util.spec_from_file_location(name.replace("-", "_"), EVID / f"{name}.py")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


PTY = load("live-pty")
READ = load("live-read")

ROOT = pathlib.Path.cwd()
VIOLA = ROOT / "target/debug/viola"
FAKE = ROOT / "target/debug/viola-fake-agent"
E2E = ROOT / "target/e2e-home"
LEDGER_PY = EVID / "live-ledger.py"
NAME = "round"
FAKE_VERSION = "2.1.302"
# `viola run`'s gate asks `--version` with no child argument, so the fake answers its default version
RUN_FAKE_VERSION = "2.1.287"
FAKE_SCRIPT = ROOT / "fixtures/fake-scripts/path4.json"
PROMPT = ("Use the AskUserQuestion tool once to ask me which of two colours I prefer, "
          "with the two options red and blue. Do nothing else.")
HEADROOM_GIB = 9
TRUST_LITERAL = READ.MODALS[0]
ANSI = re.compile(rb"\x1b\[[0-9;?<>=]*[ -/]*[@-~]|\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)|\x1b[@-_]")

LIVE = {
    "verify": {"timeout": 900, "question": 300, "expiry": 3660},
    "rehearse": {"timeout": 900, "question": 60, "expiry": 120},
}


def stamp():
    return datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%dT%H%M%SZ")


def sha16(path):
    return hashlib.sha256(pathlib.Path(path).read_bytes()).hexdigest()[:16]


def cli_dir(version):
    return pathlib.Path.home() / ".local/share/mise/installs/claude" / version


def env_for(bin_dir):
    env = PTY.declared_env()
    env["PATH"] = f"{bin_dir}:/usr/local/bin:/usr/bin:/bin"
    return env


def private_dir(path):
    path.mkdir(mode=0o700, parents=True, exist_ok=False)
    os.chmod(path, 0o700)
    return path


def write_private(path, data):
    fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
    with os.fdopen(fd, "wb") as f:
        f.write(data)


def ledger(priv, row):
    n = len(list(priv.glob("row-*.json")))
    row_file = priv / f"row-{n}.json"
    write_private(row_file, json.dumps(row).encode())
    subprocess.run([sys.executable, str(LEDGER_PY), str(READ.LEDGER), str(row_file)], cwd=ROOT,
                   stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=30, check=True)


def headroom_gib():
    st = os.statvfs("/tmp")
    return st.f_bavail * st.f_frsize // 2**30


def save_state(update):
    state = READ.read_json(READ.STATE) or {}
    state.update(update)
    tmp = READ.STATE.with_suffix(".tmp")
    tmp.write_text(json.dumps(state, sort_keys=True) + "\n", encoding="utf-8")
    os.replace(tmp, READ.STATE)


def rel(path):
    return str(pathlib.Path(path).resolve().relative_to(ROOT.resolve()))


class Session:
    """A pty in live-pty.py's form, holding counts of what it drained and a short stripped tail."""

    def __init__(self, cmd, env, cwd):
        self.master, slave = os.openpty()
        termios.tcsetwinsize(self.master, (PTY.ROWS, PTY.COLS))
        self.pid = os.fork()
        if self.pid == 0:
            os.close(self.master)
            os.chdir(cwd)
            os.login_tty(slave)
            try:
                os.execve(cmd[0], cmd, env)
            finally:
                os._exit(127)
        os.close(slave)
        self.drained = 0
        self.literals = {lit: 0 for lit in READ.TERMINAL_LITERALS}
        self.tail = b""
        self.text = ""
        self.since = ""
        self.written = []
        self.exit = None
        self.killed = False

    def _take(self, chunk):
        self.drained += len(chunk)
        data = self.tail + chunk
        for lit in self.literals:
            self.literals[lit] += data.count(lit) - self.tail.count(lit)
        self.tail = data[-16:]
        stripped = ANSI.sub(b"", chunk).decode("utf-8", "replace")
        self.text = (self.text + stripped)[-16384:]
        self.since = (self.since + stripped)[-16384:]

    def mark(self):
        """Start `since`: the stripped bytes drained from now on."""
        self.since = ""

    def pump(self, seconds):
        if self.master is None:
            time.sleep(seconds)
            return
        end = time.monotonic() + seconds
        while time.monotonic() < end and self.exit is None:
            try:
                ready, _, _ = select.select([self.master], [], [], 0.05)
            except InterruptedError:
                ready = []
            if ready:
                try:
                    chunk = os.read(self.master, 65536)
                except OSError as e:
                    if e.errno != errno.EIO:
                        raise
                    chunk = b""
                if chunk:
                    self._take(chunk)
            done, st = os.waitpid(self.pid, os.WNOHANG)
            if done:
                self.exit = os.waitstatus_to_exitcode(st)

    def write(self, data, what):
        os.write(self.master, data)
        self.written.append(what)

    def stop(self):
        """live-pty.py's stop: Ctrl-C every 500 ms, the group SIGKILLed 10 s in."""
        if self.master is None:
            return
        began, last = time.monotonic(), 0.0
        while self.exit is None:
            now = time.monotonic()
            if now - began > PTY.STOP_BOUND and not self.killed:
                self.killed = True
                try:
                    os.killpg(self.pid, signal.SIGKILL)
                except ProcessLookupError:
                    pass
            elif not self.killed and now - last >= PTY.CTRL_C_EVERY:
                try:
                    os.write(self.master, b"\x03")
                except OSError:
                    pass
                last = now
            self.pump(0.1)
        self.close()

    def kill(self):
        if self.exit is None and self.master is not None:
            self.killed = True
            try:
                os.killpg(self.pid, signal.SIGKILL)
            except ProcessLookupError:
                pass
            end = time.monotonic() + 10
            while self.exit is None and time.monotonic() < end:
                self.pump(0.1)
        self.close()

    def close(self):
        if self.master is not None:
            os.close(self.master)
            self.master = None

    def holds(self, literal):
        return literal in self.text


def ready_screen(text):
    return any(s in text for s in READ.FOOTER) or "\n" + READ.BOX_PROMPT in text


def trust_selected(text):
    at = text.rfind(TRUST_LITERAL)
    if at < 0:
        return False
    return re.search(READ.BOX_PROMPT + r"[\s\d.]*$", text[max(0, at - 24):at]) is not None


def pass_trust(sess, grant, wait=60.0):
    """The folder-trust dialog: keys only on a `yes` grant, only while the drained bytes hold the trust literal,
    at most 2 down-arrows and 1 Enter, the Enter only on a read `selected`."""
    end = time.monotonic() + wait
    while time.monotonic() < end and sess.exit is None:
        sess.pump(0.5)
        if sess.holds(TRUST_LITERAL) or ready_screen(sess.text):
            break
    if not sess.holds(TRUST_LITERAL):
        return {"trust": "no-dialog", "arrows": 0, "enters": 0}
    if grant != "yes":
        return {"trust": f"modal-refused-{grant}", "arrows": 0, "enters": 0}
    arrows = 0
    while sess.exit is None:
        sess.pump(1.0)
        if not sess.holds(TRUST_LITERAL):
            return {"trust": "dialog-gone", "arrows": arrows, "enters": 0}
        if trust_selected(sess.text):
            sess.write(b"\r", "enter")
            sess.text = ""
            sess.pump(3.0)
            return {"trust": "passed" if not sess.holds(TRUST_LITERAL) else "unpassed",
                    "arrows": arrows, "enters": 1}
        if arrows >= 2:
            return {"trust": "modal-unpassed", "arrows": arrows, "enters": 0}
        sess.write(b"\x1b[B", "down")
        arrows += 1
    return {"trust": "exited", "arrows": arrows, "enters": 0}


def viola(home, *args, env, timeout=60, stdin=subprocess.DEVNULL):
    """A direct spawn of the built viola, its output held in memory and read only for codes."""
    try:
        done = subprocess.run([str(VIOLA), "--home", str(home), *args], cwd=ROOT, env=env, stdin=stdin,
                              capture_output=True, timeout=timeout)
        return done.returncode, done.stdout, done.stderr
    except subprocess.TimeoutExpired:
        return None, b"", b""


def json_codes(out):
    """A `--json` document's closed code words only: `error` / `refusal` / `detail` / `confirmed`."""
    try:
        doc = json.loads(out.decode("utf-8", "replace").strip().splitlines()[-1])
    except (ValueError, IndexError):
        return "unparsed"
    body = doc.get("ok") if isinstance(doc.get("ok"), dict) else doc
    keep = {k: body.get(k) for k in ("error", "refusal", "detail", "confirmed") if k in body}
    return ",".join(f"{k}:{v}" for k, v in keep.items() if isinstance(v, (str, bool)) or v is None) or "none"


def events(home):
    return READ.ndjson(READ.instance_dir(home, NAME) / "events.ndjson")


def await_kind(home, kind, bound, pred=lambda e: True, sess=None, after=0):
    end = time.monotonic() + bound
    while time.monotonic() < end:
        found = [e for e in events(home)[after:] if e.get("kind") == kind and pred(e)]
        if found:
            return found[-1]
        if sess is not None:
            sess.pump(0.2)
        else:
            time.sleep(0.2)
    return None


def heartbeat_age(home):
    try:
        return time.time() - (READ.instance_dir(home, NAME) / "heartbeat").stat().st_mtime
    except OSError:
        return None


def child_starts(home):
    return sum(1 for l in READ.run_log(home, NAME)
               if l.get("event") == "process-start" and (l.get("fields") or l).get("subject") == "claude-child")


def refusal_code(stderr):
    text = stderr.decode("utf-8", "replace")
    if "is already live" in text:
        return "already-live"
    if "still running but not answering" in text:
        return "stale-heartbeat"
    return "other"


def words_or_refuse(needs, starts):
    try:
        words = READ.parse_words()
        READ.require(words, needs, starts)
    except READ.Refused as e:
        print(f"refused: {e}")
        sys.exit(3)
    return words


def close(sub, green, codes):
    word = "green" if green is True else ("unread" if green is None else "red")
    print(f"{sub}: {word} — " + " · ".join(f"{k}={v}" for k, v in codes.items()))
    return 0 if green is True else 1


# --- verify -----------------------------------------------------------------------------------------------

def verify(rehearse):
    sub = "rehearse-verify" if rehearse else "live-verify"
    if not rehearse:
        words = words_or_refuse(("cap", "cli"), 6)
        version = words["cli"]
        claude = cli_dir(version) / "claude"
    gib = headroom_gib()
    if gib < HEADROOM_GIB:
        return close(sub, False, {"headroom_gib": gib, "floor": HEADROOM_GIB})
    base = E2E / (f"viola-live-rehearsal-{stamp()}" if rehearse else f"viola-live-{stamp()}")
    made = False
    codes = {"headroom_gib": gib}
    try:
        private_dir(base)
        made = True
        home, priv = private_dir(base / "home"), private_dir(base / "priv")
        if rehearse:
            bin_dir = private_dir(priv / "bin")
            claude = bin_dir / "claude"
            shutil.copy2(FAKE, claude)
            os.chmod(claude, 0o700)
            version = FAKE_VERSION
            extra = ["--cli-version", version, "--fixtures", str(ROOT / "fixtures/claude"), "--screens",
                     "--turn-stop", "--dialogs", "--framing", "--trusted-root", str(ROOT)]
        else:
            bin_dir = cli_dir(version)
            extra = []
        env = env_for(bin_dir)
        got = subprocess.run([str(claude), *extra[:2], "--version"], env=env, capture_output=True, timeout=60)
        codes["cli_version_matches"] = got.stdout.decode().split()[:1] == [version]
        codes["viola_sha"] = sha16(VIOLA)
        if not rehearse:
            ledger(priv, {"kind": "start", "step": sub, "starts": 6, "live": True, "cli": version})
        rec = priv / "rec"
        began = time.monotonic()
        try:
            done = subprocess.run([str(VIOLA), "--home", str(home), "verify", "--record", str(rec), "--",
                                   str(claude), *extra], cwd=ROOT, env=env, stdin=subprocess.DEVNULL,
                                  capture_output=True, timeout=LIVE["verify"]["timeout"])
            code, out, err = done.returncode, done.stdout, done.stderr
        except subprocess.TimeoutExpired as e:
            code, out, err = None, e.stdout or b"", e.stderr or b""
        codes["verify_exit"] = code
        codes["verify_s"] = round(time.monotonic() - began)
        write_private(priv / "verify-stderr.txt", err)
        codes["stderr_bytes"] = len(err)
        last = (out.decode("utf-8", "replace").strip().splitlines() or [""])[-1]
        m = re.fullmatch(r"stamped (\S+)  (\d+) pass  (\d+) fail", last)
        codes["stamped"] = f"{m.group(1)}/{m.group(2)}/{m.group(3)}" if m else "none"
        recorded = rec / version
        codes["recorded_files"] = len(list(recorded.glob("*.json"))) if recorded.is_dir() else 0
        for phase, yes in sorted(READ.box([recorded]).items()) if recorded.is_dir() else []:
            codes[f"box_only_{phase}"] = yes
        green = bool(m and m.group(1) == version and m.group(3) == "0" and code == 0
                     and codes["recorded_files"] > 0 and codes["cli_version_matches"])
        if rehearse:
            ledger(priv, {"kind": "reading", "mode": "rehearsal", "step": sub,
                          "verdict": "green" if green else "red", **codes})
        else:
            ledger(priv, {"kind": "reading", "mode": "live", "step": sub,
                          "verdict": "green" if green else "red", **codes})
            save_state({"verify": {"base": rel(base), "cli": version, "green": green},
                        "recording": rel(recorded) if recorded.is_dir() else None})
            made = False
        codes["census_held"] = READ.census(base)
        return close(sub, green, codes)
    finally:
        if rehearse and made:
            shutil.rmtree(base, ignore_errors=True)


# --- the wrapped and unwrapped sessions ------------------------------------------------------------------

def stamp_rehearsal_home(home, claude, env):
    code, out, _ = viola(home, "verify", "--", str(claude), "--cli-version", RUN_FAKE_VERSION, "--fixtures",
                         str(ROOT / "fixtures/claude"), "--screens", "--turn-stop", "--dialogs", "--framing",
                         "--trusted-root", str(ROOT), env=env, timeout=LIVE["verify"]["timeout"])
    last = (out.decode("utf-8", "replace").strip().splitlines() or [""])[-1]
    return code == 0 and bool(re.fullmatch(r"stamped \S+  \d+ pass  0 fail", last))


def make_cwd(base, trust, rehearse):
    """`trust yes`: a tmpfs `proj/` that is its own git repo; `trust no`: an in-tree 0700 dir."""
    if trust == "yes" or rehearse:
        proj = private_dir(base / "proj")
        subprocess.run(["/usr/bin/git", "init", "-q"], cwd=proj, timeout=30, check=True,
                       stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        return proj
    return private_dir(ROOT / "target" / f"live-round-cwd-{stamp()}")


def receipt_keys(receipt):
    return [r.get("hex") for r in READ.ndjson(receipt) if r.get("kind") == "key"]


def box_input(text):
    """What the last box-prompt row of `text` holds after the prompt glyph, or None with no prompt row drawn."""
    at = text.rfind(READ.BOX_PROMPT)
    if at < 0:
        return None
    return re.split(r"[\r\n─│]", text[at + 1:], maxsplit=1)[0].strip()


def erase_reading(text):
    """`erased` only on a redrawn prompt row no longer holding the `x`; a row still holding it, or no redraw, stands."""
    held = box_input(text)
    return "erased" if held is not None and held != "x" else "stands"


def input_box(sess, grant, home, env, receipt, rehearse):
    """One `x` and one DEL into the input box on a `yes` grant, read back; `viola release` only when the drained
    bytes show the box erased — a standing `x` ends the step with nothing more typed or sent (inputs#I4). On any
    other grant nothing is written and the wheel is read unmoved for 2 s. Returns (reading, step goes on)."""
    before = len(events(home))
    human = lambda e: (e.get("data") or {}).get("holder") == "human"
    if grant != "yes":
        wrote = len(sess.written)
        moved = await_kind(home, "wheel", 2, human, sess=sess, after=before)
        return f"refused-{grant},written={len(sess.written) - wrote},human={moved is not None}", True
    sess.mark()
    sess.write(b"x", "input-box")
    took = await_kind(home, "wheel", 2, human, sess=sess, after=before)
    echoed = ("78" in receipt_keys(receipt)) if rehearse else (box_input(sess.since) == "x")
    sess.mark()
    sess.write(b"\x7f", "input-box")
    sess.pump(1.0)
    erase = erase_reading(sess.since)
    reading = f"echo={echoed},human={took is not None},erase={erase}"
    if erase != "erased":
        return reading, False
    code, _, _ = viola(home, "release", NAME, env=env, timeout=30)
    back = await_kind(home, "wheel", 5, lambda e: (e.get("data") or {}).get("holder") == "driver",
                      sess=sess, after=before)
    return f"{reading},release={code},driver={back is not None}", True


def wrapped(rehearse):
    sub = "rehearse-wrapped" if rehearse else "live-wrapped"
    if rehearse:
        grants = {"trust": "yes", "input-box": "yes", "statusline-read": "no"}
        timing = LIVE["rehearse"]
    else:
        words = words_or_refuse(("cap", "cli", "trust", "input-box", "statusline-read"), 1)
        grants = {k: words[k] for k in ("trust", "input-box", "statusline-read")}
        timing = LIVE["verify"]
        state = READ.read_json(READ.STATE) or {}
        v = state.get("verify") or {}
        if not (v.get("green") and v.get("cli") == words["cli"]):
            print("refused: no green live-verify for this cli")
            return 3
    codes = {}
    sess = None
    base = None
    made = []
    try:
        if rehearse:
            base = private_dir(E2E / f"viola-live-rehearsal-{stamp()}")
            made.append(base)
            home, priv = private_dir(base / "home"), private_dir(base / "priv")
            bin_dir = private_dir(priv / "bin")
            claude = bin_dir / "claude"
            shutil.copy2(FAKE, claude)
            os.chmod(claude, 0o700)
            env = env_for(bin_dir)
            if not stamp_rehearsal_home(home, claude, env):
                return close(sub, False, {"rehearsal_stamp": "red"})
            hold_s = 60
        else:
            base = ROOT / state["verify"]["base"]
            home, priv = base / "home", base / "priv"
            bin_dir = cli_dir(words["cli"])
            claude = bin_dir / "claude"
            env = env_for(bin_dir)
            hold_s = 3600
        write_private(home / "config.json", json.dumps({"v": 1, "dialog_hold_s": hold_s}).encode())
        cwd = make_cwd(base, grants["trust"], rehearse)
        if not str(cwd).startswith(str(base)):
            made.append(cwd)
        argv = [str(VIOLA), "--home", str(home), "run", NAME, "--", str(claude)]
        control = priv / "control"
        receipt = priv / "receipt.ndjson"
        if rehearse:
            write_private(control, b"")
            argv += ["--cli-version", RUN_FAKE_VERSION, "--fixtures", str(ROOT / "fixtures/claude"), "--screens",
                     "--trusted-root", str(cwd), "--script", str(FAKE_SCRIPT), "--control", str(control),
                     "--receipt", str(receipt)]
        codes["viola_sha"] = sha16(VIOLA)
        if not rehearse:
            ledger(priv, {"kind": "start", "step": sub, "starts": 1, "live": True, "cli": words["cli"]})
        since = time.time()
        sess = Session(argv, env, cwd)
        codes.update(pass_trust(sess, grants["trust"]))
        if codes["trust"] not in ("no-dialog", "passed"):
            sess.kill()
            return close(sub, False, codes)
        # (a) the start readings
        ready = await_kind(home, "session-start", 120, sess=sess)
        codes["session_start"] = ready is not None
        sess.pump(2.0)
        start = READ.start(home, NAME, since)
        codes["start"] = "green" if start.pop("green") else "red"
        codes["start_detail"] = json.dumps(start, sort_keys=True, separators=(",", ":"))
        snap = READ.snapshot(home, NAME)
        wrapper_pid, child_pid = snap.get("pid"), snap.get("child_pid")
        # (b) the name refusals, neither spawning a child
        children = child_starts(home)
        code, _, err = viola(home, "run", NAME, "--", str(claude), env=env, timeout=30)
        codes["second_run"] = f"{code}/{refusal_code(err)}"
        os.kill(wrapper_pid, signal.SIGSTOP)
        try:
            end = time.monotonic() + 20
            while (heartbeat_age(home) or 0) < 6 and time.monotonic() < end:
                time.sleep(0.2)
            code, _, err = viola(home, "run", NAME, "--", str(claude), env=env, timeout=30)
            codes["third_run"] = f"{code}/{refusal_code(err)}"
        finally:
            os.kill(wrapper_pid, signal.SIGCONT)
        end = time.monotonic() + 10
        while (heartbeat_age(home) or 99) > 5 and time.monotonic() < end:
            sess.pump(0.2)
        codes["heartbeat_live_again"] = (heartbeat_age(home) or 99) <= 5
        codes["refusal_children"] = child_starts(home) - children
        # (c) the status line, wrapped
        sl = READ.statusline(home, NAME, grants["statusline-read"])
        codes["statusline"] = "green" if sl.pop("green") else "red"
        codes["statusline_detail"] = json.dumps(sl, sort_keys=True, separators=(",", ":"))
        # (d) live: the human's keys before the hold, a standing `x` ending the step there; the rehearsal reads
        # them after the hold, because the fake agent keeps a DEL in its prompt (inputs#I4)
        go_on = True
        if not rehearse:
            codes["keys"], go_on = input_box(sess, grants["input-box"], home, env, receipt, rehearse)
            if not go_on:
                codes["ended"] = "erase-stands"
        # (e) the hold
        if go_on:
            journal = EVID / "hold-journal.md"
            sent_at = datetime.datetime.now(datetime.timezone.utc)
            if not rehearse:
                journal.write_text(
                    f"# Hold journal — {sub}\n\n- home: {rel(home)} · instance: {NAME}\n"
                    f"- send at: {sent_at.strftime('%Y-%m-%dT%H:%M:%SZ')} · expected expiry: about "
                    f"{(sent_at + datetime.timedelta(seconds=hold_s)).strftime('%Y-%m-%dT%H:%M:%SZ')}\n"
                    "- a resumed window re-reads: this journal, the gate log of entry 10, the instance's "
                    "events.ndjson, round-state.json\n", encoding="utf-8")
            prompt_file = priv / "prompt.txt"
            write_private(prompt_file, PROMPT.encode())
            before = len(events(home))
            written = len(sess.written)
            code, out, _ = viola(home, "send", NAME, "--file", str(prompt_file), "--json", env=env, timeout=120)
            codes["send"] = code
            codes["send_codes"] = json_codes(out)
            if rehearse:
                with open(control, "a", encoding="utf-8") as f:
                    f.write("go\n")
            q = await_kind(home, "question", timing["question"], sess=sess, after=before)
            codes["question"] = q is not None
            asked = time.monotonic()
            expired = await_kind(home, "dialog-expired", timing["expiry"], sess=sess, after=before) if q else None
            codes["dialog_expired"] = expired is not None
            codes["kinds_after_send"] = "/".join(str(e.get("kind")) for e in events(home)[before:])
            codes["hold_s"] = round(time.monotonic() - asked) if expired else None
            answered = [l for l in READ.run_log(home, NAME) + events(home)
                        if (l.get("event") or l.get("kind")) == "dialog-answered"]
            fields = (answered[-1].get("fields") or answered[-1].get("data") or answered[-1]) if answered else {}
            codes["deadline_hit"] = fields.get("deadline_hit")
            codes["duration_ms"] = fields.get("duration_ms")
            codes["keys_during_hold"] = len(sess.written) - written
        # (d) rehearsed: the refused arm, then the granted arm, whose standing `x` (the fake's no-erase) is the
        # stop arm; the release is then read alone, and the erase predicate over fixed texts
        if rehearse:
            codes["keys_refused_arm"], _ = input_box(sess, "unanswered", home, env, receipt, rehearse)
            codes["keys"], went_on = input_box(sess, "yes", home, env, receipt, rehearse)
            codes["keys_stop_arm"] = "stopped" if not went_on else "went-on"
            before = len(events(home))
            code, _, _ = viola(home, "release", NAME, env=env, timeout=30)
            back = await_kind(home, "wheel", 5, lambda e: (e.get("data") or {}).get("holder") == "driver",
                              sess=sess, after=before)
            codes["release_probe"] = f"release={code},driver={back is not None}"
            codes["erase_predicate"] = (erase_reading(READ.BOX_PROMPT + " x") == "stands"
                                        and erase_reading(READ.BOX_PROMPT + " ") == "erased"
                                        and erase_reading("") == "stands")
        # (f) the killed wrapper
        wrapper_started = READ.start_time(wrapper_pid)
        child_started = READ.start_time(child_pid)
        matched = wrapper_started is not None and child_started is not None
        os.kill(wrapper_pid, signal.SIGKILL)
        end = time.monotonic() + 10
        while READ.alive(child_pid, child_started) and time.monotonic() < end:
            sess.pump(0.1)
        codes["child_gone_after_kill"] = matched and not READ.alive(child_pid, child_started)
        sess.pump(1.0)
        sess.kill()
        codes["unable_bytes"] = sess.literals[b"unable: "]
        codes["hint_bytes"] = sess.literals[b"hint: "]
        codes["drained_bytes"] = sess.drained
        # (g) the census
        codes["census_held"] = READ.census(base)
        if rehearse:
            keys_green = (codes["keys_refused_arm"] == "refused-unanswered,written=0,human=False"
                          and codes["keys"] == "echo=True,human=True,erase=stands"
                          and codes["keys_stop_arm"] == "stopped"
                          and codes["release_probe"] == "release=0,driver=True" and codes["erase_predicate"])
        elif grants["input-box"] == "yes":
            keys_green = codes["keys"] == "echo=True,human=True,erase=erased,release=0,driver=True"
        else:
            keys_green = codes["keys"].startswith("refused-")
        green = bool(
            go_on and codes["session_start"] and codes["start"] == "green"
            and codes["second_run"] == "1/already-live" and codes["third_run"] == "1/stale-heartbeat"
            and codes["heartbeat_live_again"] and codes["refusal_children"] == 0 and codes["statusline"] == "green"
            and keys_green and codes["send"] == 0 and codes["question"] and codes["dialog_expired"]
            and codes["keys_during_hold"] == 0 and codes["child_gone_after_kill"]
            and codes["unable_bytes"] == 0 and codes["hint_bytes"] == 0 and codes["census_held"] == 0)
        if not rehearse:
            ledger(priv, {"kind": "reading", "mode": "live", "step": sub,
                          "verdict": "green" if green else "red", **codes})
        return close(sub, green, codes)
    finally:
        if sess is not None and sess.exit is None:
            sess.stop()
        if rehearse:
            for d in made:
                shutil.rmtree(d, ignore_errors=True)


def unwrapped(rehearse):
    sub = "rehearse-unwrapped" if rehearse else "live-unwrapped"
    if not rehearse:
        words = words_or_refuse(("cap", "cli", "trust", "statusline-read"), 1)
        state = READ.read_json(READ.STATE) or {}
        v = state.get("verify") or {}
        if not (v.get("green") and v.get("cli") == words["cli"]):
            print("refused: no green live-verify for this cli")
            return 3
    codes = {}
    made = []
    try:
        if rehearse:
            base = private_dir(E2E / f"viola-live-rehearsal-{stamp()}")
            made.append(base)
            priv = private_dir(base / "priv")
            bin_dir = private_dir(priv / "bin")
            claude = bin_dir / "claude"
            shutil.copy2(FAKE, claude)
            os.chmod(claude, 0o700)
            env = env_for(bin_dir)
            fake = ["--cli-version", RUN_FAKE_VERSION, "--fixtures", str(ROOT / "fixtures/claude"), "--screens"]
            # the main start, trusted, then the trust arms in an untrusted cwd: granted and refused
            arms = [("main", "yes", True), ("trust-granted", "yes", False), ("trust-refused", "no", False)]
            grants_sl = "no"
        else:
            base = ROOT / state["verify"]["base"]
            priv = base / "priv"
            bin_dir = cli_dir(words["cli"])
            claude = bin_dir / "claude"
            env = env_for(bin_dir)
            fake = []
            arms = [("main", words["trust"], None)]
            grants_sl = words["statusline-read"]
        codes["viola_sha"] = sha16(VIOLA)
        green = True
        for label, trust, trusted in arms:
            cwd = private_dir(base / f"proj-{label}") if rehearse else make_cwd(base, trust, False)
            if not str(cwd).startswith(str(base)):
                made.append(cwd)
            if rehearse:
                subprocess.run(["/usr/bin/git", "init", "-q"], cwd=cwd, timeout=30, check=True,
                               stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            argv = [str(claude), *fake]
            receipt = priv / f"receipt-{label}.ndjson"
            if rehearse:
                argv += ["--receipt", str(receipt)] + (["--trusted-root", str(cwd)] if trusted else [])
            else:
                ledger(priv, {"kind": "start", "step": sub, "starts": 1, "live": True, "cli": words["cli"]})
            sess = Session(argv, env, cwd)
            t = {"trust": "unread"}
            try:
                t = pass_trust(sess, trust)
                codes[f"{label}_trust"] = f"{t['trust']}/{t['arrows']}/{t['enters']}"
                if label == "main":
                    if t["trust"] not in ("no-dialog", "passed"):
                        green = False
                        continue
                    sess.pump(3.0)
                    sl = READ.statusline(None, NAME, grants_sl, child_pid=sess.pid)
                    codes["statusline"] = "green" if sl.pop("green") else "red"
                    codes["statusline_detail"] = json.dumps(sl, sort_keys=True, separators=(",", ":"))
                    green = green and codes["statusline"] == "green"
                else:
                    keys = receipt_keys(receipt)
                    codes[f"{label}_agent_keys"] = len(keys)
                    want = ("modal-unpassed/2/0" if label == "trust-granted" else "modal-refused-no/0/0")
                    green = green and codes[f"{label}_trust"] == want and "0d" not in keys and (
                        label == "trust-granted" or not keys)
            finally:
                if t["trust"] in ("no-dialog", "passed"):
                    sess.stop()
                else:
                    sess.kill()
                codes[f"{label}_stop"] = "killed" if sess.killed else f"exit-{sess.exit}"
        codes["census_held"] = READ.census(base)
        green = green and codes["census_held"] == 0
        if not rehearse:
            ledger(priv, {"kind": "reading", "mode": "live", "step": sub,
                          "verdict": "green" if green else "red", **codes})
        return close(sub, green, codes)
    finally:
        if rehearse:
            for d in made:
                shutil.rmtree(d, ignore_errors=True)


def main():
    verb = sys.argv[1] if len(sys.argv) == 2 else ""
    if not ((ROOT / "Cargo.toml").is_file() and (ROOT / ".andromeda").is_dir()):
        sys.exit("run from the repository root")
    table = {
        "rehearse-verify": lambda: verify(True), "live-verify": lambda: verify(False),
        "rehearse-wrapped": lambda: wrapped(True), "live-wrapped": lambda: wrapped(False),
        "rehearse-unwrapped": lambda: unwrapped(True), "live-unwrapped": lambda: unwrapped(False),
    }
    if verb not in table:
        sys.exit(__doc__)
    return table[verb]()


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""The live round's reader (plan.md step 5): codes, counts, booleans and durations only — never a path, a
prompt, an assistant text, a session id or a pid in what it prints.

  live-read.py words [<file>]            the founder lines: `words: 4 forks · {k} answered` (exit 3 malformed)
  live-read.py start <home> <name>       the start readings of a wrapped instance
  live-read.py statusline <home> <name>  the wrapped child's argv and instance dir (statusline-read from words)
  live-read.py box <file|dir>...         `box-only: yes|no` per recorded Screen.{ready,turn}.json
  live-read.py census <base>             processes still holding the round's base dir
  live-read.py ledger                    starts used, reds, unread in live-sessions.ndjson
  live-read.py place                     step 8: the recorded files placed (cli: 2.1.302) or carried

Run from the repository root. live-hold.py and live-tap.py load this file for the same readings.
"""
import datetime
import hashlib
import json
import os
import pathlib
import re
import shlex
import shutil
import stat
import sys
import time

EVID = pathlib.Path(__file__).resolve().parent
WORDS = EVID / "founder-words.md"
LEDGER = EVID / "live-sessions.ndjson"
STATE = EVID / "round-state.json"

# The compiled literals of viola-agent-claude's `screen::SIGNATURES` (crates/viola-agent-claude/src/screen.rs),
# mirrored here for a reader outside the product; a rig never builds a literal from screen text.
FOOTER = ("for agents", "(shift+tab to cycle)")
MODALS = ("Yes, I trust this folder", "Yes, allow external imports")
BOX_RULE, BOX_PROMPT, BOX_RULE_MIN = "─", "❯", 40
TERMINAL_LITERALS = (b"unable: ", b"hint: ")

FORKS = ("cap", "keys", "cli", "hold")
KEY_PARTS = ("trust", "input-box", "statusline-read")
HOLD_WORDS = ("stands", "moves-to-read", "stays-provisional")


class Refused(Exception):
    pass


def now():
    return datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def parse_words(path=WORDS):
    """The four lines, each `unanswered` or its answer; a malformed file is a Refused."""
    try:
        lines = pathlib.Path(path).read_text(encoding="utf-8").splitlines()
    except OSError:
        raise Refused("words-unreadable")
    lines = [l for l in lines if l.strip()]
    if len(lines) != len(FORKS):
        raise Refused("words-malformed")
    out = {}
    for fork, line in zip(FORKS, lines):
        head, sep, rest = line.partition(":")
        if head != fork or not sep:
            raise Refused("words-malformed")
        rest = rest.strip()
        if fork == "keys":
            parts = [p.strip() for p in rest.split("·")]
            if len(parts) != len(KEY_PARTS):
                raise Refused("words-malformed")
            for name, part in zip(KEY_PARTS, parts):
                word = part.split()
                if len(word) != 2 or word[0] != name or word[1] not in ("unanswered", "yes", "no"):
                    raise Refused("words-malformed")
                out[name] = word[1]
        elif rest == "unanswered":
            out[fork] = "unanswered"
        elif fork == "cap":
            m = re.fullmatch(r"(\d+)( starts?)?", rest)
            if not m:
                raise Refused("words-malformed")
            out[fork] = int(m.group(1))
        elif fork == "cli":
            if not re.fullmatch(r"\d+\.\d+\.\d+", rest):
                raise Refused("words-malformed")
            out[fork] = rest
        else:
            if rest not in HOLD_WORDS:
                raise Refused("words-malformed")
            out[fork] = rest
    return out


def answered(words):
    k = sum(1 for f in ("cap", "cli", "hold") if words[f] != "unanswered")
    return k + (1 if all(words[p] != "unanswered" for p in KEY_PARTS) else 0)


def ledger_rows():
    if not LEDGER.exists():
        return []
    rows = []
    for line in LEDGER.read_text(encoding="utf-8").splitlines():
        try:
            rows.append(json.loads(line))
        except ValueError:
            rows.append({"kind": "torn"})
    return rows


def starts_used():
    return sum(r.get("starts", 0) for r in ledger_rows() if r.get("kind") == "start" and r.get("live") is True)


def require(words, needs, starts):
    """Every line `needs` names answered, and the cap not passed by `starts` more; else a Refused naming it."""
    for fork in needs:
        if words[fork] == "unanswered":
            raise Refused(f"word {fork} unanswered")
    if starts:
        if words["cap"] == "unanswered":
            raise Refused("word cap unanswered")
        used = starts_used()
        if used + starts > words["cap"]:
            raise Refused(f"cap {used}+{starts} past {words['cap']}")


def read_json(path):
    try:
        return json.loads(pathlib.Path(path).read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None


def ndjson(path):
    try:
        text = pathlib.Path(path).read_text(encoding="utf-8")
    except OSError:
        return []
    out = []
    for line in text.splitlines():
        try:
            out.append(json.loads(line))
        except ValueError:
            out.append({"torn": True})
    return out


def instance_dir(home, name):
    return pathlib.Path(home) / "instances" / name


def snapshot(home, name):
    """The snapshot's `data` (the file is a `{v, written_at, writer, data}` envelope)."""
    doc = read_json(instance_dir(home, name) / "snapshot.json") or {}
    return doc.get("data") or {}


def run_log(home, name):
    found = sorted(pathlib.Path(home).rglob(f"run-{name}.ndjson"))
    return ndjson(found[0]) if found else []


def start_time(pid):
    try:
        text = pathlib.Path(f"/proc/{pid}/stat").read_text()
    except OSError:
        return None
    return int(text[text.rindex(")") + 2:].split()[19])


def alive(pid, started=None):
    st = start_time(pid)
    return st is not None and (started is None or st == started)


def mode(path):
    try:
        return stat.S_IMODE(os.stat(path).st_mode)
    except OSError:
        return None


def child_fds(child_pid, home, endpoint):
    """fds 0-2 on a pty, the count of fds on the viola endpoint, the count of files under the home."""
    unix = {}
    try:
        for line in pathlib.Path("/proc/net/unix").read_text().splitlines()[1:]:
            parts = line.split()
            if len(parts) >= 8:
                unix[parts[6]] = parts[7]
    except OSError:
        pass
    std_pty, on_endpoint, under_home, total = 0, 0, 0, 0
    home = str(pathlib.Path(home).resolve())
    try:
        fds = os.listdir(f"/proc/{child_pid}/fd")
    except OSError:
        return None
    for fd in fds:
        try:
            target = os.readlink(f"/proc/{child_pid}/fd/{fd}")
        except OSError:
            continue
        total += 1
        if fd in ("0", "1", "2") and target.startswith("/dev/pts/"):
            std_pty += 1
        m = re.fullmatch(r"socket:\[(\d+)\]", target)
        if m and endpoint and unix.get(m.group(1)) == endpoint:
            on_endpoint += 1
        if target.startswith(home + "/"):
            under_home += 1
    return {"std_on_pty": std_pty, "on_endpoint": on_endpoint, "under_home": under_home, "fds": total}


def start(home, name, since=None):
    """The start readings (plan.md step 5 `start`); `since` the spawn's epoch seconds for the freshness reads."""
    inst = instance_dir(home, name)
    events = ndjson(inst / "events.ndjson")
    kinds = [e.get("kind") for e in events]
    first_two = (len(events) >= 2 and events[0].get("kind") == "wheel"
                 and (events[0].get("data") or {}).get("cause") == "start"
                 and events[1].get("kind") == "session-start")
    child = [l for l in run_log(home, name)
             if l.get("event") == "process-start" and (l.get("fields") or l).get("subject") == "claude-child"]
    child_fields = (child[-1].get("fields") or child[-1]) if child else {}
    snap = snapshot(home, name)
    endpoint = snap.get("endpoint")
    sock_dir_mode = mode(os.path.dirname(endpoint)) if endpoint else None
    plugin = pathlib.Path(home) / "plugin"
    plugin_fresh = since is not None and any(p.stat().st_mtime >= since for p in plugin.rglob("hooks.json"))
    hooks = sorted(plugin.rglob("hooks.json"))
    pinned_by_hooks = False
    if hooks:
        cmds = re.findall(r'"command"\s*:\s*"([^"]+)"', hooks[-1].read_text(encoding="utf-8"))
        bin_dir = str((pathlib.Path(home) / "bin").resolve()) + "/"
        pinned_by_hooks = bool(cmds) and all(c.startswith(bin_dir) and os.path.isfile(c.split()[0]) for c in cmds)
    fds = child_fds(snap.get("child_pid"), home, endpoint) if snap.get("child_pid") else None
    r = {
        "first_two_wheel_then_session_start": first_two,
        "budget_kind_lines": sum(1 for k in kinds if k and "budget" in k),
        "child_process_start": len(child),
        "child_cli_verified": child_fields.get("cli_verified"),
        "child_pty_backend": child_fields.get("pty_backend"),
        "snapshot_cli_verified": snap.get("cli_verified"),
        "socket_dir_mode": oct(sock_dir_mode) if sock_dir_mode is not None else None,
        "socket_mode": oct(mode(endpoint)) if endpoint and mode(endpoint) is not None else None,
        "plugin_written_at_start": plugin_fresh,
        "hooks_run_pinned_copy": pinned_by_hooks,
        "child_fds": fds,
    }
    r["green"] = bool(
        first_two and r["budget_kind_lines"] == 0 and r["child_process_start"] >= 1
        and r["child_cli_verified"] is True and r["child_pty_backend"] == "openpty"
        and r["snapshot_cli_verified"] is True and r["socket_dir_mode"] == "0o700"
        and r["socket_mode"] == "0o600" and plugin_fresh and pinned_by_hooks and fds
        and fds["std_on_pty"] == 3 and fds["on_endpoint"] == 0 and fds["under_home"] == 0)
    return r


def descendants(pid):
    kids = {}
    for p in os.listdir("/proc"):
        if not p.isdigit():
            continue
        try:
            text = pathlib.Path(f"/proc/{p}/stat").read_text()
        except OSError:
            continue
        ppid = int(text[text.rindex(")") + 2:].split()[1])
        kids.setdefault(ppid, []).append(int(p))
    out, todo = [], [pid]
    while todo:
        for k in kids.get(todo.pop(), []):
            out.append(k)
            todo.append(k)
    return out


def argv(pid):
    try:
        return [a.decode("utf-8", "replace") for a in pathlib.Path(f"/proc/{pid}/cmdline").read_bytes().split(b"\0") if a]
    except OSError:
        return None


def h16(text):
    return hashlib.sha256(text.encode()).hexdigest()[:16]


def settings_fact():
    p = pathlib.Path.home() / ".claude" / "settings.json"
    try:
        data = p.read_bytes()
        return {"mtime_ns": p.stat().st_mtime_ns, "sha256": hashlib.sha256(data).hexdigest()}, data
    except OSError:
        return None, None


def statusline_hits(pid, statusline_read, window=30.0):
    """On `yes` only: `~/.claude/settings.json`'s `statusLine.command` read, kept as hashes, and every descendant
    of `pid` polled every 20 ms for `window` s; a hit is a descendant whose argv holds the command whole or
    opens with its tokens. On anything else the file is not opened."""
    if statusline_read != "yes":
        return {"statusline_read": statusline_read, "hits": "unread"}
    before, data = settings_fact()
    command = None
    if data is not None:
        try:
            command = (json.loads(data).get("statusLine") or {}).get("command")
        except ValueError:
            command = None
    if not isinstance(command, str) or not command:
        return {"statusline_read": "yes", "hits": "unread", "command": "absent"}
    whole = h16(command)
    tokens = shlex.split(command)
    lead = [h16(t) for t in tokens]
    seen = set()
    end = time.monotonic() + window
    while time.monotonic() < end:
        for d in descendants(pid):
            a = argv(d)
            if not a or d in seen:
                continue
            hashed = [h16(x) for x in a]
            if whole in hashed or hashed[:len(lead)] == lead:
                seen.add(d)
        time.sleep(0.02)
    after, _ = settings_fact()
    return {"statusline_read": "yes", "hits": len(seen), "settings_unchanged": before == after}


def statusline(home, name, statusline_read, child_pid=None, window=30.0):
    inst = instance_dir(home, name) if home else None
    snap = snapshot(home, name) if inst else {}
    pid = child_pid or snap.get("child_pid")
    a = argv(pid) if pid else None
    r = {
        "child_argv_read": a is not None,
        "settings_flag": bool(a) and any(x == "--settings" or x.startswith("--settings=") for x in a),
        "instance_settings_json": bool(inst) and (inst / "settings.json").exists(),
    }
    r.update(statusline_hits(pid, statusline_read, window) if pid else {"hits": "unread"})
    r["green"] = bool(r["child_argv_read"] and not r["settings_flag"] and not r["instance_settings_json"]
                      and (r["hits"] == "unread" or (r["hits"] > 0 and r.get("settings_unchanged"))))
    return r


def is_box_rule(row):
    rule = row.rstrip(" ")
    return len(rule) >= BOX_RULE_MIN and all(c == BOX_RULE for c in rule)


def box_only(rows):
    footer = any(any(s in r for s in FOOTER) for r in rows)
    box = any(is_box_rule(a) and b.startswith(BOX_PROMPT) for a, b in zip(rows, rows[1:]))
    return (not footer) and box


def box(paths):
    out = {}
    for p in paths:
        p = pathlib.Path(p)
        files = [p / f"Screen.{ph}.json" for ph in ("ready", "turn")] if p.is_dir() else [p]
        for f in files:
            doc = read_json(f)
            if doc is None:
                continue
            out[doc.get("screen_phase", f.stem)] = "yes" if box_only(doc.get("rows") or []) else "no"
    return out


def census(base):
    base = str(pathlib.Path(base).resolve())
    held = 0
    for p in os.listdir("/proc"):
        if not p.isdigit() or int(p) == os.getpid():
            continue
        a = argv(int(p)) or []
        try:
            cwd = os.readlink(f"/proc/{p}/cwd")
        except OSError:
            cwd = ""
        if any(base in x for x in a) or cwd == base or cwd.startswith(base + "/"):
            held += 1
    return held


def place():
    words = parse_words()
    require(words, ("cli",), 0)
    state = read_json(STATE) or {}
    rec = state.get("recording")
    tap = state.get("tap_fixture")
    root = pathlib.Path.cwd()
    placed, carried = [], []
    if words["cli"] != "2.1.302":
        carried = [n for n in ("Mcp.tools-list-1.json", "Screen.ready.json", "Screen.turn.json")]
        return {"cli_places": False, "placed": placed, "carried": carried}
    dest = root / "fixtures/claude/2.1.302"
    if tap and pathlib.Path(tap).is_file():
        shutil.copyfile(tap, dest / "Mcp.tools-list-1.json")
        placed.append("Mcp.tools-list-1.json")
    else:
        carried.append("Mcp.tools-list-1.json")
    if rec:
        for phase, yes in box([rec]).items():
            name = f"Screen.{phase}.json"
            if yes == "yes":
                shutil.copyfile(pathlib.Path(rec) / name, dest / name)
                placed.append(name)
            else:
                carried.append(name)
    return {"cli_places": True, "placed": placed, "carried": carried}


def main():
    verb = sys.argv[1] if len(sys.argv) > 1 else ""
    args = sys.argv[2:]
    try:
        if verb == "words" and len(args) <= 1:
            w = parse_words(args[0] if args else WORDS)
            print(f"words: {len(FORKS)} forks · {answered(w)} answered")
        elif verb == "start" and len(args) == 2:
            r = start(args[0], args[1])
            green = r.pop("green")
            print("start: " + ("green" if green else "red") + " — " + json.dumps(r, sort_keys=True))
            return 0 if green else 1
        elif verb == "statusline" and len(args) == 2:
            r = statusline(args[0], args[1], parse_words()["statusline-read"])
            print("statusline: " + ("green" if r.pop("green") else "red") + " — " + json.dumps(r, sort_keys=True))
        elif verb == "box" and args:
            for phase, yes in sorted(box(args).items()):
                print(f"box-only: {yes} · {phase}")
        elif verb == "census" and len(args) == 1:
            print(f"census: {census(args[0])} held")
        elif verb == "ledger" and not args:
            rows = [r for r in ledger_rows() if r.get("mode") == "live"]
            print(f"ledger: starts {starts_used()} · reds {sum(1 for r in rows if r.get('verdict') == 'red')}"
                  f" · unread {sum(1 for r in rows if r.get('verdict') == 'unread')}")
        elif verb == "place" and not args:
            r = place()
            print("place: " + json.dumps(r, sort_keys=True))
        else:
            sys.exit(__doc__)
    except Refused as e:
        print(f"refused: {e}")
        return 3
    return 0


if __name__ == "__main__":
    sys.exit(main())

