                                                            "home_is_dir=True,via_link=True")
                 and codes["fail_arm"] == f"refused:relied row {relied[-1]} reads fail"
                 and codes["fail_arm_wrote"] is False and codes["relied_count"] == 21)
        codes["census_held"] = READ.census(base)
