def scrub_frames(frames):
    """The frames as the recorder scrubs a fixture (`ledger::scrub`): the repository root → `.`, the e2e link's target
    → its in-root name, the user's home → `~`, the user word → `<user>` (whole word, any case)."""
    home = str(pathlib.Path.home())
    user = pathlib.Path.home().name
    pairs = sorted({(str(ROOT), "."), (str(E2E.resolve()), "target/e2e-home"), (home, "~")},
                   key=lambda p: -len(p[0]))
    word = re.compile(r"(?<![\w])" + re.escape(user) + r"(?![\w])", re.IGNORECASE) if user else None

    def one(text):
        for long, short in pairs:
            text = text.replace(long, short)
        return word.sub("<user>", text) if word else text

    return [{**f, "rows": [one(r) for r in f["rows"]]} for f in frames]


def keep_frames(sess, path):
    """Write the session's kept frames, scrubbed, as one JSON document (0600); returns (frames, clean)."""
    frames = scrub_frames(sess.frames)
    text = json.dumps({"v": 1, "frames": frames}, ensure_ascii=False, indent=1)
    write_private(path, (text + "\n").encode())
    clean = "/home/" not in text and "/tmp/" not in text and not re.search(
        r"(?<![\w])" + re.escape(pathlib.Path.home().name) + r"(?![\w])", text, re.IGNORECASE)
    return frames, clean


def screens_dir():
    """The local, gitignored frames dir (0700): a frame holds the CLI's text and, live, the user's own status line,
    so it never enters the chunk's work dir, a run dir or a commit (inputs#I22 item 4)."""
    if not READ.SCREENS.is_dir():
        private_dir(READ.SCREENS)
    st = READ.SCREENS.lstat()
    if not stat_ok(st):
        raise RuntimeError("screens dir not owner-only")
    return READ.SCREENS


def stat_ok(st):
    return stat.S_ISDIR(st.st_mode) and st.st_uid == os.geteuid() and st.st_mode & 0o077 == 0


def append_summary(lines):
    fd = os.open(READ.SUMMARY, os.O_WRONLY | os.O_CREAT | os.O_APPEND, 0o600)
    with os.fdopen(fd, "ab") as f:
        for line in lines:
            f.write((json.dumps(line, sort_keys=True, separators=(",", ":")) + "\n").encode())


def save_screens(sess, sub, priv, rehearse, arm=""):
    """The session's kept frames written under the local frames dir, and one closed-word summary line per frame
    appended to the evidence. Returns `frames={n},clean={b},summary={k},closed={b}` (+ the frame file's name live)."""
    name = f"screens-{sub}{'-' + arm if arm else ''}-{stamp()}.json"
    frames, clean = keep_frames(sess, screens_dir() / name)
    lines = READ.summarise(frames, sub, arm, name, rehearse)
    closed = all(READ.line_fault(line) is None for line in lines)
    append_summary(lines)
    return (f"frames={len(frames)},clean={clean},summary={len(lines)},closed={closed}"
            + ("" if rehearse else f",file={name}"))


def modal_arm(home, priv, claude, env, base, sub):
    """Rehearsal only: entry 10's shape under the fake agent — a wrapped session whose cwd the fake does not trust,
    so its modal stands; the trust grant `no` (no key); a send, which viola refuses `input-not-ready`; the witness
    read; the frames kept. Returns `{trust}/{send exit}/{witness}/frames={n},clean={b}`."""
    cwd = private_dir(base / "proj-modal")
    subprocess.run(["/usr/bin/git", "init", "-q"], cwd=cwd, timeout=30, check=True,
                   stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    argv = [str(VIOLA), "--home", str(home), "run", NAME, "--", str(claude), "--cli-version", RUN_FAKE_VERSION,
            "--fixtures", str(ROOT / "fixtures/claude"), "--screens", "--receipt", str(priv / "receipt-modal.ndjson")]
    sess = Session(argv, env, cwd)
    try:
        t = pass_trust(sess, "no")
        before = len(events(home))
        code, out, _ = viola(home, "send", NAME, "--file", str(priv / "prompt.txt"), "--json", env=env, timeout=120)
        sess.frame("after-send")
        witness = send_witness(code, json_codes(out), events(home)[before:])
        sess.kill()
        sess.frame("final")
        return f"{t['trust']}/{code}/{witness}/{save_screens(sess, sub, priv, True, 'modal')}"
    finally:
        if sess.exit is None:
            sess.kill()


def pass_trust(sess, grant, wait=60.0):
    """The folder-trust dialog: keys only on a `yes` grant, only while the screen model shows the trust literal, at
    most 2 down-arrows and 1 Enter, the Enter only on a read `selected`. A frame is kept at each decision."""
    end = time.monotonic() + wait
    while time.monotonic() < end and sess.exit is None:
        sess.pump(0.5)
        if sess.holds(TRUST_LITERAL) or ready_screen(sess.screen):
            break
    sess.frame("trust-seen")
    if not sess.holds(TRUST_LITERAL):
        return {"trust": "no-dialog", "arrows": 0, "enters": 0}
    if grant != "yes":
        return {"trust": f"modal-refused-{grant}", "arrows": 0, "enters": 0}
    arrows = 0
    while sess.exit is None:
        sess.pump(1.0)
        if not sess.holds(TRUST_LITERAL):
            sess.frame("trust-gone")
            return {"trust": "dialog-gone", "arrows": arrows, "enters": 0}
        if trust_selected(sess.screen):
            sess.frame("trust-selected")
            sess.write(b"\r", "enter")
            sess.pump(3.0)
            sess.frame("trust-after-enter")
            return {"trust": "passed" if not sess.holds(TRUST_LITERAL) else "unpassed",
                    "arrows": arrows, "enters": 1}
        if arrows >= 2:
            sess.frame("trust-unpassed")
            return {"trust": "modal-unpassed", "arrows": arrows, "enters": 0}
        sess.write(b"\x1b[B", "down")
        arrows += 1
    return {"trust": "exited", "arrows": arrows, "enters": 0}


def viola(home, *args, env, timeout=60, stdin=subprocess.DEVNULL):
    """A direct spawn of the built viola, its output held in memory and read only for codes."""
    try:
        done = subprocess.run([str(VIOLA), "--home", str(home), *args], cwd=ROOT, env=env, stdin=stdin,
                              capture_output=True, timeout=timeout)
        return done.returncode, done.stdout, done.stderr
    except subprocess.TimeoutExpired:
        return None, b"", b""


def json_codes(out):
    """A `--json` document's closed code words only: `error` / `refusal` / `detail` / `confirmed`."""
    try:
        doc = json.loads(out.decode("utf-8", "replace").strip().splitlines()[-1])
    except (ValueError, IndexError):
        return "unparsed"
    body = doc.get("ok") if isinstance(doc.get("ok"), dict) else doc
    keep = {k: body.get(k) for k in ("error", "refusal", "detail", "confirmed") if k in body}
    return ",".join(f"{k}:{v}" for k, v in keep.items() if isinstance(v, (str, bool)) or v is None) or "none"


def events(home, name=NAME):
    return READ.ndjson(READ.instance_dir(home, name) / "events.ndjson")


def await_kind(home, kind, bound, pred=lambda e: True, sess=None, after=0, name=NAME):
    end = time.monotonic() + bound
    while time.monotonic() < end:
        found = [e for e in events(home, name)[after:] if e.get("kind") == kind and pred(e)]
        if found:
            return found[-1]
        if sess is not None:
            sess.pump(0.2)
        else:
            time.sleep(0.2)
    return None


def heartbeat_age(home):
    try:
        return time.time() - (READ.instance_dir(home, NAME) / "heartbeat").stat().st_mtime
    except OSError:
        return None


def child_starts(home):
    return sum(1 for l in READ.run_log(home, NAME)
               if l.get("event") == "process-start" and (l.get("fields") or l).get("subject") == "claude-child")


def refusal_code(stderr):
    text = stderr.decode("utf-8", "replace")
    if "is already live" in text:
        return "already-live"
    if "still running but not answering" in text:
        return "stale-heartbeat"
    return "other"


def words_or_refuse(needs, starts):
    try:
        words = READ.parse_words()
        READ.require(words, needs, starts)
        words["latest"] = READ.latest(words["cli"])
    except READ.Refused as e:
        print(f"refused: {e}")
        sys.exit(3)
    return words


def close(sub, green, codes):
    word = "green" if green is True else ("unread" if green is None else "red")
    print(f"{sub}: {word} — " + " · ".join(f"{k}={v}" for k, v in codes.items()))
    return 0 if green is True else 1


# --- verify -----------------------------------------------------------------------------------------------

def verify(rehearse):
    sub = "rehearse-verify" if rehearse else "live-verify"
    if not rehearse:
        words = words_or_refuse(("cap", "cli"), 6)
        version = words["cli"]
        claude = cli_dir(version) / "claude"
    gib = headroom_gib()
    if gib < HEADROOM_GIB:
        return close(sub, False, {"headroom_gib": gib, "floor": HEADROOM_GIB})
    base = E2E / (f"viola-live-rehearsal-{stamp()}" if rehearse else f"viola-live-{stamp()}")
    made = False
    codes = {"headroom_gib": gib}
    try:
        private_dir(base)
        made = True
        home, priv = private_dir(base / "home"), private_dir(base / "priv")
        if rehearse:
            bin_dir = private_dir(priv / "bin")
            claude = bin_dir / "claude"
            shutil.copy2(FAKE, claude)
            os.chmod(claude, 0o700)
            version = FAKE_VERSION
            extra = ["--cli-version", version, "--fixtures", str(ROOT / "fixtures/claude"), "--screens",
                     "--turn-stop", "--dialogs", "--framing", "--trusted-root", str(ROOT)]
        else:
            bin_dir = cli_dir(version)
            extra = []
        env = env_for(bin_dir)
        got = subprocess.run([str(claude), *extra[:2], "--version"], env=env, capture_output=True, timeout=60)
        codes["cli_version_matches"] = got.stdout.decode().split()[:1] == [version]
        codes["viola_sha"] = sha16(VIOLA)
        if not rehearse:
            codes["latest"] = words["latest"]
        if not rehearse:
            ledger(priv, {"kind": "start", "step": sub, "starts": 6, "live": True, "cli": version, "latest": words["latest"]})
        rec = priv / "rec"
        began = time.monotonic()
        try:
            done = subprocess.run([str(VIOLA), "--home", str(home), "verify", "--record", str(rec), "--",
                                   str(claude), *extra], cwd=ROOT, env=env, stdin=subprocess.DEVNULL,
                                  capture_output=True, timeout=LIVE["verify"]["timeout"])
            code, out, err = done.returncode, done.stdout, done.stderr
        except subprocess.TimeoutExpired as e:
            code, out, err = None, e.stdout or b"", e.stderr or b""
        codes["verify_exit"] = code
        codes["verify_s"] = round(time.monotonic() - began)
        write_private(priv / "verify-stderr.txt", err)
        codes["stderr_bytes"] = len(err)
        last = (out.decode("utf-8", "replace").strip().splitlines() or [""])[-1]
        m = re.fullmatch(r"stamped (\S+)  (\d+) pass  (\d+) fail", last)
        codes["stamped"] = f"{m.group(1)}/{m.group(2)}/{m.group(3)}" if m else "none"
        recorded = rec / version
        codes["recorded_files"] = len(list(recorded.glob("*.json"))) if recorded.is_dir() else 0
        for phase, yes in sorted(READ.box([recorded]).items()) if recorded.is_dir() else []:
            codes[f"box_only_{phase}"] = yes
        green = bool(m and m.group(1) == version and m.group(3) == "0" and code == 0
                     and codes["recorded_files"] > 0 and codes["cli_version_matches"])
        # The stamp (what entries 10 and 11 need) and the recording (CARRY 2) are stated apart (inputs#I9).
        state = {"verify": {"base": rel(base), "home": rel(home), "cli": version,
                            "stamp": "pass" if m and m.group(1) == version and m.group(3) == "0" else "fail",
                            "recording": "written" if codes["recorded_files"] else "refused",
                            "entry": "green" if green else "red"},
                 "recording": rel(recorded) if recorded.is_dir() else None}
        if rehearse:
            saved = priv / "round-state.json"
            save_state(state, saved)
            back = (READ.read_json(saved) or {}).get("verify") or {}
            codes["state_saved"] = (back.get("base") == rel(base) and (ROOT / back["base"]).is_dir()
                                    and back.get("base", "").startswith("target/e2e-home/"))
            green = green and codes["state_saved"]
            ledger(priv, {"kind": "reading", "mode": "rehearsal", "step": sub,
                          "verdict": "green" if green else "red", **codes})
        else:
            ledger(priv, {"kind": "reading", "mode": "live", "step": sub,
                          "verdict": "green" if green else "red", **codes})
            save_state(state)
            made = False
        codes["census_held"] = READ.census(base)
        return close(sub, green, codes)
    finally:
        if rehearse and made:
            shutil.rmtree(base, ignore_errors=True)


# --- the wrapped and unwrapped sessions ------------------------------------------------------------------

def stamp_rehearsal_home(home, claude, env):
    code, out, _ = viola(home, "verify", "--", str(claude), "--cli-version", RUN_FAKE_VERSION, "--fixtures",
                         str(ROOT / "fixtures/claude"), "--screens", "--turn-stop", "--dialogs", "--framing",
                         "--trusted-root", str(ROOT), env=env, timeout=LIVE["verify"]["timeout"])
    last = (out.decode("utf-8", "replace").strip().splitlines() or [""])[-1]
    return code == 0 and bool(re.fullmatch(r"stamped \S+  \d+ pass  0 fail", last))


def fresh_proj(base):
    """A `proj-{stamp}/` no earlier start made: what an earlier start left under the base stays as found (inputs#I26)."""
    name, n = f"proj-{stamp()}", 1
    while (base / name).exists():
        n += 1
        name = f"proj-{stamp()}-{n}"
    return private_dir(base / name)


def make_cwd(base, trust, rehearse):
    """`trust yes`: a fresh tmpfs `proj-{stamp}/` that is its own git repo; `trust no`: an in-tree 0700 dir."""
    if trust == "yes" or rehearse:
        proj = fresh_proj(base)
        subprocess.run(["/usr/bin/git", "init", "-q"], cwd=proj, timeout=30, check=True,
                       stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        return proj
    return private_dir(ROOT / "target" / f"live-round-cwd-{stamp()}")


def receipt_keys(receipt):
    return [r.get("hex") for r in READ.ndjson(receipt) if r.get("kind") == "key"]


def box_reading(screen):
    """`erased` when the screen model's prompt row stands and no longer holds the `x`; `stands` otherwise."""
    held = screen.box_input()
    return "erased" if held is not None and held != "x" else "stands"


def input_box(sess, grant, home, env, receipt, rehearse):
    """One `x` and one DEL into the input box on a `yes` grant, the echo and the box read from the screen model (the
    fake agent draws no echo: its key receipt there), then no further key whatever the box reads, and `viola release`
    (inputs#I16: the send after it is the second witness). On any other grant nothing is written and the wheel is read
    unmoved for 2 s. Returns the reading and the count of keys written after the DEL."""
    before = len(events(home))
    human = lambda e: (e.get("data") or {}).get("holder") == "human"
    if grant != "yes":
        wrote = len(sess.written)
        moved = await_kind(home, "wheel", 2, human, sess=sess, after=before)
        return f"refused-{grant},written={len(sess.written) - wrote},human={moved is not None}"
    sess.write(b"x", "input-box")
    took = await_kind(home, "wheel", 2, human, sess=sess, after=before)
    sess.pump(0.5)
    sess.frame("after-x")
    echoed = ("78" in receipt_keys(receipt)) if rehearse else (sess.screen.box_input() == "x")
    sess.write(b"\x7f", "input-box")
    sess.pump(1.0)
    sess.frame("after-del")
    box = box_reading(sess.screen)
    after_del = len(sess.written)
    code, _, _ = viola(home, "release", NAME, env=env, timeout=30)
    back = await_kind(home, "wheel", 5, lambda e: (e.get("data") or {}).get("holder") == "driver",
                      sess=sess, after=before)
    return (f"echo={echoed},human={took is not None},box={box},release={code},driver={back is not None},"
            f"keys_after_del={len(sess.written) - after_del}")


def send_witness(code, out_codes, later):
    """The send's outcome read as the box's second witness (inputs#I16, inputs#I19): `empty` on a confirmed send;
    `unread` on `input-not-ready` (no input box stood, so nothing about the box is read); `x-stood` on another
    `not-delivered` (the text delivered beside a residue: no matching `prompt-submitted`) or a `wheel` line `human`
    after the send began; else `unread`."""
    if "detail:input-not-ready" in out_codes:
        return "unread"
    if any(e.get("kind") == "wheel" and (e.get("data") or {}).get("holder") == "human" for e in later) \
            or "not-delivered" in out_codes:
        return "x-stood"
    if code == 0 and any(e.get("kind") == "send-confirmed" for e in later):
        return "empty"
    return "unread"


def witness_controls():
    """The witness's known readings on fixed outcomes: entry 10's `input-not-ready` → `unread`; a residue's
    `no-prompt-submitted` → `x-stood`; a confirmed send → `empty`."""
    confirmed = [{"kind": "send-issued"}, {"kind": "prompt-submitted"}, {"kind": "send-confirmed"}]
    return (send_witness(13, "refusal:not-delivered,detail:input-not-ready", [{"kind": "send-refused"}]) == "unread"
            and send_witness(13, "refusal:not-delivered,detail:no-prompt-submitted",
                             [{"kind": "send-issued"}, {"kind": "send-refused"}]) == "x-stood"
            and send_witness(0, "none", confirmed) == "empty")


def wrapped(rehearse):
    sub = "rehearse-wrapped" if rehearse else "live-wrapped"
    if rehearse:
        grants = {"trust": "yes", "input-box": "yes", "statusline-read": "no"}
        timing = LIVE["rehearse"]
    else:
        words = words_or_refuse(("cap", "cli", "trust", "input-box", "statusline-read"), 1)
        grants = {k: words[k] for k in ("trust", "input-box", "statusline-read")}
        timing = LIVE["verify"]
        state = READ.read_json(READ.STATE) or {}
        v = state.get("verify") or {}
        if not (v.get("stamp") == "pass" and v.get("cli") == words["cli"] and v.get("home")):
            print("refused: no green live-verify for this cli")
            return 3
    codes = {}
    sess = None
    base = None
    made = []
    try:
        if rehearse:
            base = private_dir(E2E / f"viola-live-rehearsal-{stamp()}")
            made.append(base)
            home, priv = private_dir(base / "home"), private_dir(base / "priv")
            bin_dir = private_dir(priv / "bin")
            claude = bin_dir / "claude"
            shutil.copy2(FAKE, claude)
            os.chmod(claude, 0o700)
            env = env_for(bin_dir)
            if not stamp_rehearsal_home(home, claude, env):
                return close(sub, False, {"rehearsal_stamp": "red"})
            hold_s = 60
        else:
            base = ROOT / state["verify"]["base"]
            home, priv = ROOT / state["verify"]["home"], base / "priv"
            bin_dir = cli_dir(words["cli"])
            claude = bin_dir / "claude"
            env = env_for(bin_dir)
            hold_s = 3600
        write_private(home / "config.json", json.dumps({"v": 1, "dialog_hold_s": hold_s}).encode())
        cwd = make_cwd(base, grants["trust"], rehearse)
        if not str(cwd).startswith(str(base)):
            made.append(cwd)
        argv = [str(VIOLA), "--home", str(home), "run", NAME, "--", str(claude)]
        control = priv / "control"
        receipt = priv / "receipt.ndjson"
        if rehearse:
            write_private(control, b"")
            argv += ["--cli-version", RUN_FAKE_VERSION, "--fixtures", str(ROOT / "fixtures/claude"), "--screens",
                     "--trusted-root", str(cwd), "--script", str(FAKE_SCRIPT), "--control", str(control),
                     "--receipt", str(receipt)]
        codes["viola_sha"] = sha16(VIOLA)
        if not rehearse:
            codes["latest"] = words["latest"]
        if not rehearse:
            ledger(priv, {"kind": "start", "step": sub, "starts": 1, "live": True, "cli": words["cli"], "latest": words["latest"]})
        since = time.time()
        sess = Session(argv, env, cwd)
        codes.update(pass_trust(sess, grants["trust"]))
        if codes["trust"] not in ("no-dialog", "passed"):
            sess.kill()
            sess.frame("final")
            codes["screens"] = save_screens(sess, sub, priv, rehearse)
            return close(sub, False, codes)
        # (a) the start readings
        ready = await_kind(home, "session-start", 120, sess=sess)
        codes["session_start"] = ready is not None
        sess.pump(2.0)
        sess.frame("start")
        start_rows = scrub_frames(sess.frames[-1:])[0]["rows"]
        start = READ.start(home, NAME, since)
        codes["start"] = "green" if start.pop("green") else "red"
        codes["start_detail"] = json.dumps(start, sort_keys=True, separators=(",", ":"))
        snap = READ.snapshot(home, NAME)
        wrapper_pid, child_pid = snap.get("pid"), snap.get("child_pid")
        # (b) the name refusals, neither spawning a child
        children = child_starts(home)
        code, _, err = viola(home, "run", NAME, "--", str(claude), env=env, timeout=30)
        codes["second_run"] = f"{code}/{refusal_code(err)}"
        os.kill(wrapper_pid, signal.SIGSTOP)
        try:
            end = time.monotonic() + 20
            while (heartbeat_age(home) or 0) < 6 and time.monotonic() < end:
                time.sleep(0.2)
            code, _, err = viola(home, "run", NAME, "--", str(claude), env=env, timeout=30)
            codes["third_run"] = f"{code}/{refusal_code(err)}"
        finally:
            os.kill(wrapper_pid, signal.SIGCONT)
        end = time.monotonic() + 10
        while (heartbeat_age(home) or 99) > 5 and time.monotonic() < end:
            sess.pump(0.2)
        codes["heartbeat_live_again"] = (heartbeat_age(home) or 99) <= 5
        codes["refusal_children"] = child_starts(home) - children
        # (c) the status line, wrapped: live, the verdict is the start frame's status row (inputs#I29)
        status = None if rehearse else READ.status_row(start_rows)
        sl = READ.statusline(home, NAME, grants["statusline-read"], status=status)
        codes["statusline"] = "green" if sl.pop("green") else "red"
        codes["statusline_detail"] = json.dumps(sl, sort_keys=True, separators=(",", ":"))
        # (d) live: the human's keys before the hold, the box read and recorded, no further key either way, then
        # release and the send, whose outcome is the box's second witness (inputs#I16); the rehearsal reads them after
        # the hold, because the fake agent keeps a DEL in its prompt (inputs#I4)
        go_on = True
        if not rehearse:
            codes["keys"] = input_box(sess, grants["input-box"], home, env, receipt, rehearse)
        # (e) the hold
        if go_on:
            journal = EVID / "hold-journal.md"
            sent_at = datetime.datetime.now(datetime.timezone.utc)
            if not rehearse:
                journal.write_text(
                    f"# Hold journal — {sub}\n\n- home: {rel(home)} · instance: {NAME}\n"
                    f"- send at: {sent_at.strftime('%Y-%m-%dT%H:%M:%SZ')} · expected expiry: about "
                    f"{(sent_at + datetime.timedelta(seconds=hold_s)).strftime('%Y-%m-%dT%H:%M:%SZ')}\n"
                    "- a resumed window re-reads: this journal, the gate log of entry 10, the instance's "
                    "events.ndjson, round-state.json\n", encoding="utf-8")
            prompt_file = priv / "prompt.txt"
            write_private(prompt_file, PROMPT.encode())
            before = len(events(home))
            written = len(sess.written)
            code, out, _ = viola(home, "send", NAME, "--file", str(prompt_file), "--json", env=env, timeout=120)
            codes["send"] = code
            codes["send_codes"] = json_codes(out)
            sess.frame("after-send")
            if not rehearse and grants["input-box"] == "yes":
                codes["box_witness"] = send_witness(code, codes["send_codes"], events(home)[before:])
            if rehearse:
                with open(control, "a", encoding="utf-8") as f:
                    f.write("go\n")
            q = await_kind(home, "question", timing["question"], sess=sess, after=before)
            codes["question"] = q is not None
            sess.frame("question" if q else "no-question")
            asked = time.monotonic()
            expired = await_kind(home, "dialog-expired", timing["expiry"], sess=sess, after=before) if q else None
            codes["dialog_expired"] = expired is not None
            if q:
                sess.frame("expired" if expired else "no-expiry")
            codes["kinds_after_send"] = "/".join(str(e.get("kind")) for e in events(home)[before:])
            codes["hold_s"] = round(time.monotonic() - asked) if expired else None
            answered = [l for l in READ.run_log(home, NAME) + events(home)
                        if (l.get("event") or l.get("kind")) == "dialog-answered"]
            fields = (answered[-1].get("fields") or answered[-1].get("data") or answered[-1]) if answered else {}
            codes["deadline_hit"] = fields.get("deadline_hit")
            codes["duration_ms"] = fields.get("duration_ms")
            codes["keys_during_hold"] = len(sess.written) - written
        # (d) rehearsed: the refused arm, then the granted arm, whose `x` stands (the fake's no-erase): nothing typed
        # after the DEL, release, and the send after it reads the true «stands» — not delivered (inputs#I16); and the
        # screen model's known readings on synthetic streams of both renderer shapes
        if rehearse:
            codes["keys_refused_arm"] = input_box(sess, "unanswered", home, env, receipt, rehearse)
            codes["keys"] = input_box(sess, "yes", home, env, receipt, rehearse)
            before = len(events(home))
            code, out, _ = viola(home, "send", NAME, "--file", str(priv / "prompt.txt"), "--json", env=env,
                                 timeout=120)
            codes["stands_arm_send"] = f"{code}/{send_witness(code, json_codes(out), events(home)[before:])}"
            codes["screen_model"] = screen_controls()
        # (f) the killed wrapper
        sess.frame("before-kill")
        wrapper_started = READ.start_time(wrapper_pid)
        child_started = READ.start_time(child_pid)
        matched = wrapper_started is not None and child_started is not None
        os.kill(wrapper_pid, signal.SIGKILL)
        end = time.monotonic() + 10
        while READ.alive(child_pid, child_started) and time.monotonic() < end:
            sess.pump(0.1)
        codes["child_gone_after_kill"] = matched and not READ.alive(child_pid, child_started)
        sess.pump(1.0)
        sess.kill()
        sess.frame("final")
        codes["unable_bytes"] = sess.literals[b"unable: "]
        codes["hint_bytes"] = sess.literals[b"hint: "]
        codes["drained_bytes"] = sess.drained
        codes["screens"] = save_screens(sess, sub, priv, rehearse)
        # (h) rehearsed: entry 10's shape under the fake — a dialog over a wrapped session, the send refused
        # `input-not-ready`, the witness `unread`, the frames kept (inputs#I19)
        if rehearse:
            codes["modal_arm"] = modal_arm(home, priv, claude, env, base, sub)
            codes["witness_controls"] = witness_controls()
        # (g) the census
        codes["census_held"] = READ.census(base)
        if rehearse:
            frames, clean = (codes["screens"].split(",") + ["", ""])[:2]
            keys_green = (codes["keys_refused_arm"] == "refused-unanswered,written=0,human=False"
                          and codes["keys"] == "echo=True,human=True,box=stands,release=0,driver=True,keys_after_del=0"
                          and codes["stands_arm_send"] == "13/x-stood" and codes["screen_model"]
                          and codes["modal_arm"].startswith("modal-refused-no/13/unread/frames=")
                          and ",clean=True,summary=" in codes["modal_arm"]
                          and codes["modal_arm"].endswith(",closed=True") and codes["witness_controls"]
                          and int(frames.split("=")[1]) >= 6 and clean == "clean=True"
                          and codes["screens"].endswith(",closed=True"))
        elif grants["input-box"] == "yes":
            keys_green = (codes["keys"].startswith("echo=True,human=True,box=")
                          and codes["keys"].endswith(",release=0,driver=True,keys_after_del=0")
                          and codes.get("box_witness") == "empty")
        else:
            keys_green = codes["keys"].startswith("refused-")
        green = bool(
            go_on and codes["session_start"] and codes["start"] == "green"
            and codes["second_run"] == "1/already-live" and codes["third_run"] == "1/stale-heartbeat"
            and codes["heartbeat_live_again"] and codes["refusal_children"] == 0 and codes["statusline"] == "green"
            and keys_green and codes["send"] == 0 and codes["question"] and codes["dialog_expired"]
            and codes["keys_during_hold"] == 0 and codes["child_gone_after_kill"]
            and codes["unable_bytes"] == 0 and codes["hint_bytes"] == 0 and codes["census_held"] == 0)
        if not rehearse:
            ledger(priv, {"kind": "reading", "mode": "live", "step": sub,
                          "verdict": "green" if green else "red", **codes})
        return close(sub, green, codes)
    finally:
        if sess is not None and sess.exit is None:
            sess.stop()
        if sess is not None and "screens" not in codes:
            sess.frame("final")
            save_screens(sess, sub, priv, rehearse)
        if rehearse:
            for d in made:
                shutil.rmtree(d, ignore_errors=True)


