            else:
                ledger(priv, {"kind": "start", "step": sub, "starts": 1, "live": True, "cli": words["cli"], "latest": words["latest"]})
            sess = Session(argv, env, cwd)
            t = {"trust": "unread"}
            try:
                t = pass_trust(sess, trust)
                codes[f"{label}_trust"] = f"{t['trust']}/{t['arrows']}/{t['enters']}"
                if label == "main":
                    if t["trust"] not in ("no-dialog", "passed"):
                        green = False
                        continue
                    sess.pump(3.0)
                    sess.frame("start")
                    status = None if rehearse else READ.status_row(scrub_frames(sess.frames[-1:])[0]["rows"])
                    sl = READ.statusline(None, NAME, grants_sl, child_pid=sess.pid, status=status)
                    codes["statusline"] = "green" if sl.pop("green") else "red"
                    codes["statusline_detail"] = json.dumps(sl, sort_keys=True, separators=(",", ":"))
                    green = green and codes["statusline"] == "green"
                else:
                    keys = receipt_keys(receipt)
                    codes[f"{label}_agent_keys"] = len(keys)
                    want = ("modal-unpassed/2/0" if label == "trust-granted" else "modal-refused-no/0/0")
                    green = green and codes[f"{label}_trust"] == want and "0d" not in keys and (
                        label == "trust-granted" or not keys)
            finally:
                if t["trust"] in ("no-dialog", "passed"):
                    sess.stop()
