        state_a = priv / "round-state-a.json"
        try:
            v = derive(base, scratch_ledger, RUN_FAKE_VERSION, state_a, True)
            back = (READ.read_json(state_a) or {}).get("verify") or {}
            codes["pass_arm"] = (f"written,stamp={back.get('stamp')},recording={back.get('recording')},"
                                 f"entry={back.get('entry')},home_is_dir={(ROOT / back.get('home', '-')).is_dir()},"
                                 f"via_link={back.get('base', '').startswith('target/e2e-home/')}")
            codes["provenance_keys"] = ",".join(sorted(v["from"]))
        except READ.Refused as e:
            codes["pass_arm"] = f"refused:{e}"
        stamps_file = home / "ledger" / "stamps.json"
        doc = json.loads(stamps_file.read_bytes())
        relied, _ = relied_ids()
        doc["data"]["versions"][RUN_FAKE_VERSION]["rows"][relied[-1]] = "fail"
        write_private(stamps_file, json.dumps(doc).encode())
        state_b = priv / "round-state-b.json"
        try:
            derive(base, scratch_ledger, RUN_FAKE_VERSION, state_b, True)
            codes["fail_arm"] = "written"
        except READ.Refused as e:
            codes["fail_arm"] = f"refused:{e}"
        codes["fail_arm_wrote"] = state_b.exists()
        codes["relied_count"] = len(relied)
        green = (codes["stamped"] and codes["pass_arm"] == ("written,stamp=pass,recording=refused,entry=red,"
                                                            "home_is_dir=True,via_link=True")
                 and codes["fail_arm"] == f"refused:relied row {relied[-1]} reads fail"
                 and codes["fail_arm_wrote"] is False and codes["relied_count"] == 21)
        codes["census_held"] = READ.census(base)
        return close(sub, green, codes)
    finally:
        shutil.rmtree(base, ignore_errors=True)


def tree_state(path):
    """Every entry under `path` with its kind, size and mtime: what a later start must leave as found."""
    return sorted((str(p.relative_to(path)), p.is_dir(), p.lstat().st_size, p.lstat().st_mtime_ns)
                  for p in path.rglob("*"))


def await_new_start(home, count, sess, bound=120):
    """A `session-start` beyond the `count` the log held before this start (or in a log rewritten since)."""
    end = time.monotonic() + bound
    while time.monotonic() < end:
        if sum(1 for e in events(home) if e.get("kind") == "session-start") > count:
            return True
        sess.pump(0.2)
    return False


def rehearse_reuse():
    """Step 3e (c), no start: a fake home already holding a `proj/` and an instance whose wrapper was SIGKILLed (as
    entry 10 left its kept home), then a second wrapped and an unwrapped start through the live arm's `make_cwd` and
    name, each in a fresh `proj-{stamp}/`, the earlier `proj/` left as found."""
    sub = "rehearse-reuse"
    codes = {}
    sessions = []
    base = private_dir(E2E / f"viola-live-rehearsal-{stamp()}")
    try:
        home, priv = private_dir(base / "home"), private_dir(base / "priv")
        bin_dir = private_dir(priv / "bin")
        claude = bin_dir / "claude"
        shutil.copy2(FAKE, claude)
        os.chmod(claude, 0o700)
        env = env_for(bin_dir)
        if not stamp_rehearsal_home(home, claude, env):
            return close(sub, False, {"rehearsal_stamp": "red"})
        write_private(home / "config.json", json.dumps({"v": 1, "dialog_hold_s": 60}).encode())
        fake = ["--cli-version", RUN_FAKE_VERSION, "--fixtures", str(ROOT / "fixtures/claude"), "--screens"]
        codes["viola_sha"] = sha16(VIOLA)
        # the used home: a `proj/` and a wrapped instance killed as live-wrapped's step (f) kills it
        proj = private_dir(base / "proj")
        subprocess.run(["/usr/bin/git", "init", "-q"], cwd=proj, timeout=30, check=True,
                       stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        first = Session([str(VIOLA), "--home", str(home), "run", NAME, "--", str(claude), *fake,
                         "--trusted-root", str(proj)], env, proj)
        sessions.append(first)
        codes["first_session_start"] = await_new_start(home, 0, first)
        snap = READ.snapshot(home, NAME)
        wrapper_pid, child_pid = snap.get("pid"), snap.get("child_pid")
        child_started = READ.start_time(child_pid)
        os.kill(wrapper_pid, signal.SIGKILL)
        end = time.monotonic() + 10
        while READ.alive(child_pid, child_started) and time.monotonic() < end:
            first.pump(0.1)
        codes["first_killed"] = not READ.alive(child_pid, child_started)
        first.kill()
        proj_before = tree_state(proj)
        starts_before = sum(1 for e in events(home) if e.get("kind") == "session-start")
        # the second wrapped start, live-form: make_cwd's `trust yes` arm and the same name
        cwd = make_cwd(base, "yes", False)
        codes["wrapped_cwd_fresh"] = cwd.name.startswith("proj-") and cwd != proj
        second = Session([str(VIOLA), "--home", str(home), "run", NAME, "--", str(claude), *fake,
                          "--trusted-root", str(cwd)], env, cwd)
        sessions.append(second)
        codes["wrapped_trust"] = pass_trust(second, "yes")["trust"]
        codes["wrapped_session_start"] = await_new_start(home, starts_before, second)
        second.stop()
        codes["wrapped_stop"] = "killed" if second.killed else f"exit-{second.exit}"
        # the second unwrapped start, live-form, in its own fresh cwd
        cwd2 = make_cwd(base, "yes", False)
        codes["unwrapped_cwd_fresh"] = cwd2.name.startswith("proj-") and cwd2 not in (proj, cwd)
        third = Session([str(claude), *fake, "--trusted-root", str(cwd2)], env, cwd2)
        sessions.append(third)
        codes["unwrapped_trust"] = pass_trust(third, "yes")["trust"]
        third.pump(2.0)
        codes["unwrapped_ready"] = ready_screen(third.screen)
        third.stop()
        codes["unwrapped_stop"] = "killed" if third.killed else f"exit-{third.exit}"
        codes["proj_left_as_found"] = tree_state(proj) == proj_before
        codes["instance_dir_stands"] = READ.instance_dir(home, NAME).is_dir()
        codes["census_held"] = READ.census(base)
        green = bool(codes["first_session_start"] and codes["first_killed"] and codes["wrapped_cwd_fresh"]
                     and codes["wrapped_trust"] in ("no-dialog", "passed") and codes["wrapped_session_start"]
                     and codes["unwrapped_cwd_fresh"] and codes["unwrapped_trust"] in ("no-dialog", "passed")
                     and codes["unwrapped_ready"] and codes["proj_left_as_found"] and codes["instance_dir_stands"]
