        "rehearse-unwrapped": lambda: unwrapped(True), "live-unwrapped": lambda: unwrapped(False),
        "rehearse-derive": rehearse_derive, "rehearse-reuse": rehearse_reuse,
        "rehearse-trust-form": rehearse_trust_form,
        "rehearse-trusted": rehearse_trusted, "live-trusted": live_trusted, "trust-record": trust_record_read,
    }
    if verb not in table:
        sys.exit(__doc__)
    return table[verb]()


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""The live round's reader (plan.md step 5): codes, counts, booleans and durations only — never a path, a
prompt, an assistant text, a session id or a pid in what it prints.

  live-read.py words [<file>]            the founder lines: `words: 4 forks · {k} answered` (exit 3 malformed)
  live-read.py start <home> <name>       the start readings of a wrapped instance
  live-read.py statusline <home> <name>  the wrapped child's argv and instance dir (statusline-read from words)
  live-read.py latest [<link>]           mise's `latest` against the `cli:` line: match, or refused (exit 3)
  live-read.py box <file|dir>...       `box-only: yes|no` per recorded Screen.{ready,turn}.json
  live-read.py census <base>             processes still holding the round's base dir
  live-read.py ledger                    starts used, reds, unread in live-sessions.ndjson
  live-read.py place                     step 8: the recorded files placed (cli: 2.1.302) or carried
  live-read.py status-row <frame file>   step 3f: a kept frame's status row (present, place, sha256), no text
  live-read.py resummarise <frame file>  step 3f: that file's summary lines re-derived in place
  live-read.py screens-check [<summary> [<work dir>]]
                                         step 3c: the landed screens summary in closed words, no frame file landed

Run from the repository root. live-hold.py and live-tap.py load this file for the same readings.
"""
import datetime
import hashlib
import json
import os
import pathlib
import re
import shlex
import shutil
import stat
import sys
import time

EVID = pathlib.Path(__file__).resolve().parent
WORDS = EVID / "founder-words.md"
LEDGER = EVID / "live-sessions.ndjson"
STATE = EVID / "round-state.json"
LATEST = pathlib.Path.home() / ".local/share/mise/installs/claude/latest"

# The compiled literals of viola-agent-claude's `screen::SIGNATURES` (crates/viola-agent-claude/src/screen.rs),
# mirrored here for a reader outside the product; a rig never builds a literal from screen text.
FOOTER = ("for agents", "(shift+tab to cycle)")
MODALS = ("Yes, I trust this folder", "Yes, allow external imports")
BOX_RULE, BOX_PROMPT, BOX_RULE_MIN = "─", "❯", 40
TERMINAL_LITERALS = (b"unable: ", b"hint: ")

# The kept screens (plan step 3c, inputs#I22 item 4): frames only under a gitignored local path, the operator's to read
# and delete; what lands is one closed-word line per frame.
SCREENS = pathlib.Path.cwd() / "target/live-round-screens"
SUMMARY = EVID / "screens-summary.ndjson"
RUNS = pathlib.Path.cwd() / ".andromeda/runs"
SUMMARY_KEYS = {"v", "sub", "arm", "label", "found", "selected", "rows", "sha256", "file", "rehearse"}
SUBS = ("live-wrapped", "live-unwrapped", "rehearse-wrapped", "rehearse-unwrapped", "rehearse-trust-form",
        "live-trusted", "rehearse-trusted")
ARMS = ("", "main", "trust-granted", "trust-refused", "modal", "granted", "stuck", "other", "wrapped")
LABELS = ("trust-seen", "trust-gone", "trust-selected", "trust-after-enter", "trust-unpassed", "start", "after-x",
          "after-del", "after-send", "question", "no-question", "expired", "no-expiry", "before-kill", "final")
FOUND = ("trust-dialog", "input-box", "question", "none", "unknown-modal")
POST_SEND = ("after-send", "question", "no-question", "expired", "no-expiry")
FRAME_FILE = re.compile(r"screens-(live|rehearse)-(wrapped|unwrapped|trust-form|trusted)"
                        r"(-(main|trust-granted|trust-refused|modal|granted|stuck|other|wrapped))?"
                        r"-\d{8}T\d{6}Z\.json")
OPTION = re.compile(r"\s*(" + BOX_PROMPT + r"\s*)?\d+\.\s")

FORKS = ("cap", "keys", "cli", "hold")
KEY_PARTS = ("trust", "input-box", "statusline-read")
HOLD_WORDS = ("stands", "moves-to-read", "stays-provisional")


class Refused(Exception):
    pass


def now():
    return datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def parse_words(path=WORDS):
    """The four lines, each `unanswered` or its answer; a malformed file is a Refused."""
    try:
        lines = pathlib.Path(path).read_text(encoding="utf-8").splitlines()
    except OSError:
        raise Refused("words-unreadable")
    lines = [l for l in lines if l.strip()]
    if len(lines) != len(FORKS):
        raise Refused("words-malformed")
    out = {}
    for fork, line in zip(FORKS, lines):
        head, sep, rest = line.partition(":")
        if head != fork or not sep:
            raise Refused("words-malformed")
        rest = rest.strip()
        if fork == "keys":
            parts = [p.strip() for p in rest.split("·")]
            if len(parts) != len(KEY_PARTS):
                raise Refused("words-malformed")
            for name, part in zip(KEY_PARTS, parts):
                word = part.split()
                if len(word) != 2 or word[0] != name or word[1] not in ("unanswered", "yes", "no"):
                    raise Refused("words-malformed")
                out[name] = word[1]
        elif rest == "unanswered":
            out[fork] = "unanswered"
        elif fork == "cap":
            m = re.fullmatch(r"(\d+)( starts?)?", rest)
            if not m:
                raise Refused("words-malformed")
            out[fork] = int(m.group(1))
        elif fork == "cli":
            if not re.fullmatch(r"\d+\.\d+\.\d+", rest):
                raise Refused("words-malformed")
            out[fork] = rest
        else:
            if rest not in HOLD_WORDS:
                raise Refused("words-malformed")
            out[fork] = rest
    return out


def answered(words):
    k = sum(1 for f in ("cap", "cli", "hold") if words[f] != "unanswered")
    return k + (1 if all(words[p] != "unanswered" for p in KEY_PARTS) else 0)


def ledger_rows():
    if not LEDGER.exists():
        return []
    rows = []
    for line in LEDGER.read_text(encoding="utf-8").splitlines():
        try:
            rows.append(json.loads(line))
        except ValueError:
            rows.append({"kind": "torn"})
    return rows


def starts_used():
    return sum(r.get("starts", 0) for r in ledger_rows() if r.get("kind") == "start" and r.get("live") is True)


def require(words, needs, starts):
    """Every line `needs` names answered, and the cap not passed by `starts` more; else a Refused naming it."""
    for fork in needs:
        if words[fork] == "unanswered":
            raise Refused(f"word {fork} unanswered")
    if starts:
        if words["cap"] == "unanswered":
            raise Refused("word cap unanswered")
        used = starts_used()
        if used + starts > words["cap"]:
            raise Refused(f"cap {used}+{starts} past {words['cap']}")


def latest(cli, link=None):
    """The version mise's `latest` link resolves to, when it is `cli`; else a Refused (plan step 3a). The link is
    only read, never moved."""
    link = pathlib.Path(link) if link else LATEST
    try:
        version = pathlib.Path(os.readlink(link)).name
    except OSError:
        raise Refused("latest unread")
    if version != cli:
        raise Refused(f"latest {version} is not {cli}")
    return version


def read_json(path):
    try:
        return json.loads(pathlib.Path(path).read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None


def ndjson(path):
    try:
        text = pathlib.Path(path).read_text(encoding="utf-8")
    except OSError:
        return []
    out = []
    for line in text.splitlines():
        try:
            out.append(json.loads(line))
        except ValueError:
            out.append({"torn": True})
    return out


def instance_dir(home, name):
    return pathlib.Path(home) / "instances" / name


def snapshot(home, name):
    """The snapshot's `data` (the file is a `{v, written_at, writer, data}` envelope)."""
    doc = read_json(instance_dir(home, name) / "snapshot.json") or {}
    return doc.get("data") or {}


def run_log(home, name):
    found = sorted(pathlib.Path(home).rglob(f"run-{name}.ndjson"))
    return ndjson(found[0]) if found else []


def start_time(pid):
    try:
        text = pathlib.Path(f"/proc/{pid}/stat").read_text()
    except OSError:
        return None
    return int(text[text.rindex(")") + 2:].split()[19])


def alive(pid, started=None):
    st = start_time(pid)
    return st is not None and (started is None or st == started)


def mode(path):
    try:
        return stat.S_IMODE(os.stat(path).st_mode)
    except OSError:
        return None


def child_fds(child_pid, home, endpoint):
    """fds 0-2 on a pty, the count of fds on the viola endpoint, the count of files under the home."""
    unix = {}
    try:
        for line in pathlib.Path("/proc/net/unix").read_text().splitlines()[1:]:
            parts = line.split()
            if len(parts) >= 8:
                unix[parts[6]] = parts[7]
    except OSError:
        pass
    std_pty, on_endpoint, under_home, total = 0, 0, 0, 0
    home = str(pathlib.Path(home).resolve())
    try:
        fds = os.listdir(f"/proc/{child_pid}/fd")
    except OSError:
        return None
    for fd in fds:
        try:
            target = os.readlink(f"/proc/{child_pid}/fd/{fd}")
        except OSError:
            continue
        total += 1
        if fd in ("0", "1", "2") and target.startswith("/dev/pts/"):
            std_pty += 1
        m = re.fullmatch(r"socket:\[(\d+)\]", target)
        if m and endpoint and unix.get(m.group(1)) == endpoint:
            on_endpoint += 1
        if target.startswith(home + "/"):
            under_home += 1
    return {"std_on_pty": std_pty, "on_endpoint": on_endpoint, "under_home": under_home, "fds": total}


def start(home, name, since=None):
    """The start readings (plan.md step 5 `start`); `since` the spawn's epoch seconds for the freshness reads."""
    inst = instance_dir(home, name)
    events = ndjson(inst / "events.ndjson")
    kinds = [e.get("kind") for e in events]
    first_two = (len(events) >= 2 and events[0].get("kind") == "wheel"
                 and (events[0].get("data") or {}).get("cause") == "start"
                 and events[1].get("kind") == "session-start")
    child = [l for l in run_log(home, name)
             if l.get("event") == "process-start" and (l.get("fields") or l).get("subject") == "claude-child"]
    child_fields = (child[-1].get("fields") or child[-1]) if child else {}
    snap = snapshot(home, name)
    endpoint = snap.get("endpoint")
    sock_dir_mode = mode(os.path.dirname(endpoint)) if endpoint else None
    plugin = pathlib.Path(home) / "plugin"
    plugin_fresh = since is not None and any(p.stat().st_mtime >= since for p in plugin.rglob("hooks.json"))
    hooks = sorted(plugin.rglob("hooks.json"))
    pinned_by_hooks = False
    if hooks:
        cmds = re.findall(r'"command"\s*:\s*"([^"]+)"', hooks[-1].read_text(encoding="utf-8"))
        bin_dir = str((pathlib.Path(home) / "bin").resolve()) + "/"
        pinned_by_hooks = bool(cmds) and all(c.startswith(bin_dir) and os.path.isfile(c.split()[0]) for c in cmds)
    fds = child_fds(snap.get("child_pid"), home, endpoint) if snap.get("child_pid") else None
    r = {
        "first_two_wheel_then_session_start": first_two,
        "budget_kind_lines": sum(1 for k in kinds if k and "budget" in k),
        "child_process_start": len(child),
        "child_cli_verified": child_fields.get("cli_verified"),
        "child_pty_backend": child_fields.get("pty_backend"),
        "snapshot_cli_verified": snap.get("cli_verified"),
        "socket_dir_mode": oct(sock_dir_mode) if sock_dir_mode is not None else None,
        "socket_mode": oct(mode(endpoint)) if endpoint and mode(endpoint) is not None else None,
        "plugin_written_at_start": plugin_fresh,
        "hooks_run_pinned_copy": pinned_by_hooks,
        "child_fds": fds,
    }
    r["green"] = bool(
        first_two and r["budget_kind_lines"] == 0 and r["child_process_start"] >= 1
        and r["child_cli_verified"] is True and r["child_pty_backend"] == "openpty"
        and r["snapshot_cli_verified"] is True and r["socket_dir_mode"] == "0o700"
        and r["socket_mode"] == "0o600" and plugin_fresh and pinned_by_hooks and fds
        and fds["std_on_pty"] == 3 and fds["on_endpoint"] == 0 and fds["under_home"] == 0)
    return r


def descendants(pid):
    kids = {}
    for p in os.listdir("/proc"):
        if not p.isdigit():
            continue
        try:
            text = pathlib.Path(f"/proc/{p}/stat").read_text()
        except OSError:
            continue
        ppid = int(text[text.rindex(")") + 2:].split()[1])
        kids.setdefault(ppid, []).append(int(p))
    out, todo = [], [pid]
    while todo:
        for k in kids.get(todo.pop(), []):
            out.append(k)
            todo.append(k)
    return out


def argv(pid):
    try:
        return [a.decode("utf-8", "replace") for a in pathlib.Path(f"/proc/{pid}/cmdline").read_bytes().split(b"\0") if a]
    except OSError:
        return None


def h16(text):
    return hashlib.sha256(text.encode()).hexdigest()[:16]


def settings_fact():
    p = pathlib.Path.home() / ".claude" / "settings.json"
    try:
        data = p.read_bytes()
        return {"mtime_ns": p.stat().st_mtime_ns, "sha256": hashlib.sha256(data).hexdigest()}, data
    except OSError:
        return None, None


def statusline_hits(pid, statusline_read, window=30.0):
    """On `yes` only: `~/.claude/settings.json`'s `statusLine.command` read, kept as hashes, and every descendant
    of `pid` polled every 20 ms for `window` s; a hit is a descendant whose argv holds the command whole or
    opens with its tokens. On anything else the file is not opened."""
    if statusline_read != "yes":
        return {"statusline_read": statusline_read, "hits": "unread"}
    before, data = settings_fact()
    command = None
    if data is not None:
        try:
            command = (json.loads(data).get("statusLine") or {}).get("command")
        except ValueError:
            command = None
    if not isinstance(command, str) or not command:
        return {"statusline_read": "yes", "hits": "unread", "command": "absent"}
    whole = h16(command)
    tokens = shlex.split(command)
    lead = [h16(t) for t in tokens]
    seen = set()
    end = time.monotonic() + window
    while time.monotonic() < end:
        for d in descendants(pid):
            a = argv(d)
            if not a or d in seen:
                continue
            hashed = [h16(x) for x in a]
            if whole in hashed or hashed[:len(lead)] == lead:
                seen.add(d)
        time.sleep(0.02)
    after, _ = settings_fact()
    return {"statusline_read": "yes", "hits": len(seen), "settings_unchanged": before == after}


def statusline(home, name, statusline_read, child_pid=None, window=30.0, status=None):
    """The settings facts, `hits` as a named column; with `status` (a live start's `status_row` reading) the verdict
    is the screen's status row present, never the hit count (inputs#I29)."""
    inst = instance_dir(home, name) if home else None
    snap = snapshot(home, name) if inst else {}
    pid = child_pid or snap.get("child_pid")
    a = argv(pid) if pid else None
    r = {
        "child_argv_read": a is not None,
        "settings_flag": bool(a) and any(x == "--settings" or x.startswith("--settings=") for x in a),
        "instance_settings_json": bool(inst) and (inst / "settings.json").exists(),
    }
    r.update(statusline_hits(pid, statusline_read, window) if pid else {"hits": "unread"})
    settled = r["child_argv_read"] and not r["settings_flag"] and not r["instance_settings_json"]
    if status is None:
        r["green"] = bool(settled and (r["hits"] == "unread" or (r["hits"] > 0 and r.get("settings_unchanged"))))
    else:
        r["status_row"] = "present" if status[0] else "absent"
        r["status_below_rule"] = status[1]
        r["status_sha256"] = status[2]
        r["green"] = bool(settled and status[0] and r.get("settings_unchanged", True) is not False)
    return r


def is_box_rule(row):
    rule = row.rstrip(" ")
    return len(rule) >= BOX_RULE_MIN and all(c == BOX_RULE for c in rule)


def box_only(rows):
    footer = any(any(s in r for s in FOOTER) for r in rows)
    box = any(is_box_rule(a) and b.startswith(BOX_PROMPT) for a, b in zip(rows, rows[1:]))
    return (not footer) and box


def frame_sha(rows):
    return hashlib.sha256("\n".join(rows).encode()).hexdigest()


def found(rows, label):
    """The known literal a frame holds, as one closed word: the compiled trust literal, a selector dialog (a
    question once a send was made, else unknown), the input box, or none."""
    if any(MODALS[0] in r for r in rows):
        return "trust-dialog"
    block, _ = option_block(rows)
    if block or any(m in r for r in rows for m in MODALS[1:]):
        return "question" if label in POST_SEND else "unknown-modal"
    if box_only(rows) or any(any(s in r for s in FOOTER) for r in rows):
        return "input-box"
    return "none"


def text_col(row):
    """The column an option's text starts at: past the selector glyph and its space, or past the indent."""
    lead = len(row) - len(row.lstrip())
    return lead + 2 if row.lstrip().startswith(BOX_PROMPT) else lead


def option_block(rows):
    """(the option rows' indices, the marked one's) of a selector dialog, numbered or not (inputs#I29): the row the
    selector glyph opens — never an input box's prompt row, which sits right below a box rule — and the non-blank rows
    beside it whose text starts at its column. With no glyph row, the numbered rows alone, none marked."""
    glyph = [i for i, r in enumerate(rows) if r.lstrip().startswith(BOX_PROMPT)
             and not (i > 0 and is_box_rule(rows[i - 1]))]
    if not glyph:
        return [i for i, r in enumerate(rows) if OPTION.match(r)], None
    g = glyph[0]
    col = text_col(rows[g])
    same = lambda i: rows[i].strip() and not is_box_rule(rows[i]) and text_col(rows[i]) == col
    lo = g
    while lo > 0 and same(lo - 1):
        lo -= 1
    hi = g
    while hi + 1 < len(rows) and same(hi + 1):
        hi += 1
    return list(range(lo, hi + 1)), g


def selected(rows):
    """The index of the option row the selector glyph marks among the dialog's option rows, numbered or not, or
    None."""
    block, g = option_block(rows)
    return block.index(g) if g is not None else None


def status_row(rows):
    """CARRY 3's screen reading (inputs#I29): the first non-blank row below the input box's lower rule that holds no
    footer literal. Returns (present, its index below that rule, its sha256); never its text."""
    tops = [j for j in range(len(rows) - 1) if is_box_rule(rows[j]) and rows[j + 1].startswith(BOX_PROMPT)]
    if not tops:
        return False, None, None
    lower = next((j for j in range(tops[-1] + 2, len(rows)) if is_box_rule(rows[j])), None)
    if lower is None:
        return False, None, None
    for j in range(lower + 1, len(rows)):
        if rows[j].strip() and not any(s in rows[j] for s in FOOTER):
            return True, j - lower, hashlib.sha256(rows[j].encode()).hexdigest()
    return False, None, None


def status_row_file(path):
    """(exit code, line) for a kept frame file: its `start` frame, else its last frame holding an input box."""
    p = pathlib.Path(path)
    if not p.is_file():
        return 1, "status-row: unread — frame absent"
    data = p.read_bytes()
    try:
        frames = json.loads(data).get("frames", [])
    except ValueError:
        return 1, "status-row: unread — frame unparsed"
    pick = [f for f in frames if f.get("label") == "start"] or [
        f for f in frames if found(f.get("rows", []), f.get("label")) == "input-box"]
    if not pick:
        return 1, f"status-row: unread — no input-box frame · file sha256 {hashlib.sha256(data).hexdigest()}"
    f = pick[-1]
    present, k, sha = status_row(f.get("rows", []))
    file_sha = hashlib.sha256(data).hexdigest()
    if not present:
        return 1, f"status-row: absent — frame {f.get('label')} · file sha256 {file_sha}"
    return 0, f"status-row: present — below-rule {k} · sha256 {sha} · frame {f.get('label')} · file sha256 {file_sha}"


def resummarise(path, summary=SUMMARY):
    """Re-derive one kept frame file's summary lines in place (its sub, arm and rehearse kept); no other line moves."""
    p = pathlib.Path(path)
    frames = json.loads(p.read_bytes()).get("frames", [])
    raw = summary.read_bytes().splitlines()
    lines = [json.loads(r) for r in raw]
    mine = [i for i, l in enumerate(lines) if l.get("file") == p.name]
    if len(mine) != len(frames):
        raise Refused(f"{len(mine)} summary lines for {len(frames)} frames")
    first = lines[mine[0]]
    fresh = summarise(frames, first["sub"], first["arm"], p.name, first["rehearse"])
    changed = sum(1 for i, f in zip(mine, fresh) if lines[i] != f)
    for i, f in zip(mine, fresh):
        raw[i] = json.dumps(f, sort_keys=True, separators=(",", ":")).encode()
    tmp = summary.with_name(summary.name + ".tmp")
    fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
    with os.fdopen(fd, "wb") as fh:
        fh.write(b"\n".join(raw) + b"\n")
    os.replace(tmp, summary)
    return len(mine), changed


def summarise(frames, sub, arm, file, rehearse):
    return [{"v": 1, "sub": sub, "arm": arm, "label": f["label"], "found": found(f["rows"], f["label"]),
             "selected": selected(f["rows"]), "rows": len(f["rows"]), "sha256": frame_sha(f["rows"]),
             "file": file, "rehearse": rehearse} for f in frames]


def line_fault(line):
    """None when a summary line is closed words only, else the closed code of its first fault."""
    if not isinstance(line, dict) or set(line) != SUMMARY_KEYS:
        return "keys"
    checks = (
        ("v", line["v"] == 1), ("sub", line["sub"] in SUBS), ("arm", line["arm"] in ARMS),
        ("label", line["label"] in LABELS), ("found", line["found"] in FOUND),
        ("selected", line["selected"] is None or (type(line["selected"]) is int and line["selected"] >= 0)),
        ("rows", type(line["rows"]) is int and line["rows"] >= 0),
        ("sha256", isinstance(line["sha256"], str) and re.fullmatch(r"[0-9a-f]{64}", line["sha256"]) is not None),
        ("file", isinstance(line["file"], str) and FRAME_FILE.fullmatch(line["file"]) is not None),
        ("rehearse", type(line["rehearse"]) is bool))
    return next((name for name, ok in checks if not ok), None)


def screens_check(summary=SUMMARY, work_dir=EVID.parent, runs=RUNS, screens=SCREENS):
    """(clean, codes): every summary line closed, no frame file under the work dir or a run dir, each local frame
    that still stands hashing to its line."""
    landed = [p for d in (work_dir, runs) if d.is_dir() for p in d.rglob("screens-*.json")]
    if landed:
        return False, "frame-file-landed"
    if not summary.is_file():
        return False, "summary-absent"
    lines, local, deleted = 0, 0, 0
    shas = {}
    with open(summary, "rb") as f:
        for raw in f.read(MAX_SUMMARY + 1).splitlines():
            try:
                line = json.loads(raw)
            except ValueError:
                return False, "unparsed-line"
            fault = line_fault(line)
            if fault:
                return False, f"open-{fault}"
            lines += 1
            name = line["file"]
            if name not in shas:
                path = screens / name
                shas[name] = None
                if path.is_file():
                    doc = read_json(path) or {}
                    shas[name] = {frame_sha(fr.get("rows", [])) for fr in doc.get("frames", [])}
            if shas[name] is None:
                deleted += 1
            elif line["sha256"] in shas[name]:
                local += 1
            else:
                return False, "hash-mismatch"
    if lines == 0:
        return False, "summary-empty"
    return True, f"{lines} lines · {local} frames local · {deleted} deleted"


MAX_SUMMARY = 16 * 1024 * 1024


def box(paths):
    out = {}
    for p in paths:
        p = pathlib.Path(p)
        files = [p / f"Screen.{ph}.json" for ph in ("ready", "turn")] if p.is_dir() else [p]
        for f in files:
            doc = read_json(f)
            if doc is None:
                continue
            out[doc.get("screen_phase", f.stem)] = "yes" if box_only(doc.get("rows") or []) else "no"
    return out


def census(base):
    base = str(pathlib.Path(base).resolve())
    held = 0
    for p in os.listdir("/proc"):
        if not p.isdigit() or int(p) == os.getpid():
            continue
        a = argv(int(p)) or []
        try:
            cwd = os.readlink(f"/proc/{p}/cwd")
        except OSError:
            cwd = ""
        if any(base in x for x in a) or cwd == base or cwd.startswith(base + "/"):
            held += 1
    return held


def place():
    words = parse_words()
    require(words, ("cli",), 0)
    state = read_json(STATE) or {}
    rec = state.get("recording")
    tap = state.get("tap_fixture")
    root = pathlib.Path.cwd()
    placed, carried = [], []
    if words["cli"] != "2.1.302":
        carried = [n for n in ("Mcp.tools-list-1.json", "Screen.ready.json", "Screen.turn.json")]
        return {"cli_places": False, "placed": placed, "carried": carried}
    dest = root / "fixtures/claude/2.1.302"
    if tap and pathlib.Path(tap).is_file():
        shutil.copyfile(tap, dest / "Mcp.tools-list-1.json")
        placed.append("Mcp.tools-list-1.json")
    else:
        carried.append("Mcp.tools-list-1.json")
    if rec:
        for phase, yes in box([rec]).items():
            name = f"Screen.{phase}.json"
            if yes == "yes":
                shutil.copyfile(pathlib.Path(rec) / name, dest / name)
                placed.append(name)
            else:
                carried.append(name)
    return {"cli_places": True, "placed": placed, "carried": carried}


def main():
    verb = sys.argv[1] if len(sys.argv) > 1 else ""
    args = sys.argv[2:]
    try:
        if verb == "words" and len(args) <= 1:
            w = parse_words(args[0] if args else WORDS)
            print(f"words: {len(FORKS)} forks · {answered(w)} answered")
        elif verb == "latest" and len(args) <= 1:
            w = parse_words()
            require(w, ("cli",), 0)
            print(f"latest: {latest(w['cli'], args[0] if args else None)} · cli {w['cli']} · match")
        elif verb == "start" and len(args) == 2:
            r = start(args[0], args[1])
            green = r.pop("green")
            print("start: " + ("green" if green else "red") + " — " + json.dumps(r, sort_keys=True))
            return 0 if green else 1
        elif verb == "statusline" and len(args) == 2:
            r = statusline(args[0], args[1], parse_words()["statusline-read"])
            print("statusline: " + ("green" if r.pop("green") else "red") + " — " + json.dumps(r, sort_keys=True))
        elif verb == "box" and args:
            for phase, yes in sorted(box(args).items()):
                print(f"box-only: {yes} · {phase}")
        elif verb == "census" and len(args) == 1:
            print(f"census: {census(args[0])} held")
        elif verb == "ledger" and not args:
            rows = [r for r in ledger_rows() if r.get("mode") == "live"]
            print(f"ledger: starts {starts_used()} · reds {sum(1 for r in rows if r.get('verdict') == 'red')}"
                  f" · unread {sum(1 for r in rows if r.get('verdict') == 'unread')}")
        elif verb == "status-row" and len(args) == 1:
            code, line = status_row_file(args[0])
            print(line)
            return code
        elif verb == "resummarise" and len(args) == 1:
            n, changed = resummarise(args[0])
            print(f"resummarise: {n} lines · {changed} changed")
        elif verb == "screens-check" and len(args) <= 2:
            ok, codes = screens_check(*(pathlib.Path(a) for a in args))
            print(f"screens-check: {'clean' if ok else 'red'} — {codes}")
            return 0 if ok else 1
        elif verb == "place" and not args:
            r = place()
            print("place: " + json.dumps(r, sort_keys=True))
        else:
            sys.exit(__doc__)
    except Refused as e:
        print(f"refused: {e}")
        return 3
    return 0


if __name__ == "__main__":
    sys.exit(main())

