def tree_state(path):
    """Every entry under `path` with its kind, size and mtime: what a later start must leave as found."""
    return sorted((str(p.relative_to(path)), p.is_dir(), p.lstat().st_size, p.lstat().st_mtime_ns)
                  for p in path.rglob("*"))


def await_new_start(home, count, sess, bound=120):
    """A `session-start` beyond the `count` the log held before this start (or in a log rewritten since)."""
    end = time.monotonic() + bound
    while time.monotonic() < end:
        if sum(1 for e in events(home) if e.get("kind") == "session-start") > count:
            return True
        sess.pump(0.2)
    return False


def rehearse_reuse():
    """Step 3e (c), no start: a fake home already holding a `proj/` and an instance whose wrapper was SIGKILLed (as
    entry 10 left its kept home), then a second wrapped and an unwrapped start through the live arm's `make_cwd` and
