# The measured 2.1.325 trust form (inputs#I29), drawn by a stub the rehearsal writes: two UNNUMBERED option rows, the
# selector on the non-trust row by default, moved one row down on a down-arrow; an Enter on the trust row draws an
# input box. Its option texts are stand-ins but the compiled trust literal; its mode comes from a file beside it,
# because `viola run` adds its own arguments.
TRUST_FORM_STUB = r'''#!/usr/bin/python3
import os, sys, tty
here = os.path.dirname(os.path.abspath(sys.argv[0]))
if "--version" in sys.argv[1:]:
    print("2.1.287 (Claude Code)")
    sys.exit(0)
mode = open(os.path.join(here, "trust-form-mode")).read().strip()
literal = "Yes, proceed" if mode == "other" else "Yes, I trust this folder"
rule = "─" * 80
def draw_dialog(sel):
    opts = ["No, exit", literal]
    rows = ["", rule, " Accessing workspace:", "", " Stand-in dialog text.", ""]
    rows += [(" ❯ " if i == sel else "   ") + o for i, o in enumerate(opts)]
    rows += ["", " Enter to confirm · Esc to cancel"]
    os.write(1, ("\x1b[2J\x1b[H" + "\r\n".join(rows)).encode())
def draw_box():
    rows = [" Stand-in banner", "", "", rule, "❯ ", rule, "  stand-in status row",
            "  ⏵⏵ auto mode on (shift+tab to cycle) · ← for agents"]
    os.write(1, ("\x1b[2J\x1b[H" + "\r\n".join(rows)).encode())
tty.setraw(0)
sel, passed = 0, False
draw_dialog(sel)
while True:
    data = os.read(0, 64)
    if not data or b"\x03" in data:
        sys.exit(0)
    if passed:
        continue
    for _ in range(data.count(b"\x1b[B")):
        if mode != "stuck":
            sel = min(sel + 1, 1)
    if b"\r" in data and sel == 1 and mode == "granted":
        passed = True
        draw_box()
    else:
        draw_dialog(sel)
'''


def rehearse_trust_form():
