        sess.kill()
        codes["other_screens"] = save_screens(sess, sub, priv, True, "other")
        other = t["trust"] == "no-dialog" and not sess.written
        # wrapped: the same keys through `viola run`'s stdin; the wheel `human` after them, `driver` after the release
        home = private_dir(base / "home")
        sess, t, by = arm("wrapped", "granted", wrapped_home=home)
        codes["wrapped_trust"] = f"{t['trust']}/{t['arrows']}/{t['enters']}"
        human = await_kind(home, "wheel", 5, lambda e: (e.get("data") or {}).get("holder") == "human", sess=sess)
        codes["wrapped_wheel_human"] = human is not None
        before = len(events(home))
        code, _, _ = viola(home, "release", NAME, env=env, timeout=30)
        driver = await_kind(home, "wheel", 5, lambda e: (e.get("data") or {}).get("holder") == "driver",
                            sess=sess, after=before)
        codes["wrapped_release"] = code
        codes["wrapped_wheel_driver"] = driver is not None
        sess.frame("final")
        sess.stop()
        codes["wrapped_screens"] = save_screens(sess, sub, priv, True, "wrapped")
        wrapped_ok = (codes["wrapped_trust"] == "passed/1/1" and codes["wrapped_wheel_human"]
                      and codes["wrapped_release"] == 0 and codes["wrapped_wheel_driver"])
        codes["census_held"] = READ.census(base)
        screens_ok = all(",clean=True," in codes[f"{a}_screens"] and codes[f"{a}_screens"].endswith(",closed=True")
                         for a in ("granted", "stuck", "other", "wrapped"))
        green = bool(granted and stuck and other and wrapped_ok and screens_ok and codes["census_held"] == 0)
        return close(sub, green, codes)
    finally:
        for s in sessions:
            if s.exit is None:
                s.kill()
        shutil.rmtree(base, ignore_errors=True)


# --- the tenth start: a short wrapped start in a cwd the CLI already trusts (step 3g) ----------------------------

TRUSTED = "trusted"
TRUSTED_CWD = "proj-20261115T095240Z"
CLAUDE_JSON = pathlib.Path.home() / ".claude.json"
CLAUDE_JSON_MAX = 16 * 1024 * 1024
TRUSTED_BOUND_S = 300
STRIP_NAMES = re.compile(r"[A-Z][A-Z0-9_]*(,[A-Z][A-Z0-9_]*)*")
STRIP_PROBE = ("CLAUDE_CODE_REHEARSAL_PROBE", "rehearsal-probe-value-7f3a")


def trust_record(path, cwd):
    """The CLI's own trust record for `cwd` as one word — `true` · `false` · `absent` · `unreadable` — from ONE
    read-only, bounded read of `path`; nothing is written and no value but the word leaves this function. The key is
    the cwd as the CLI sees it: the resolved path a child chdir'd there reads from getcwd."""
    try:
        with open(path, "rb") as f:
            data = f.read(CLAUDE_JSON_MAX + 1)
    except OSError:
        return "unreadable"
    if len(data) > CLAUDE_JSON_MAX:
        return "unreadable"
    try:
        doc = json.loads(data)
    except ValueError:
        return "unreadable"
    projects = doc.get("projects") if isinstance(doc, dict) else None
    rec = projects.get(os.path.realpath(cwd)) if isinstance(projects, dict) else None
    if not isinstance(rec, dict) or "hasTrustDialogAccepted" not in rec:
        return "absent"
    return "true" if rec["hasTrustDialogAccepted"] is True else "false"


def trusted_preflight(home, cwd, claude_json):
    """None when the start may go; else the refusal, before any ledger row or spawn."""
    if not pathlib.Path(cwd).is_dir():
        return "cwd absent"
    if trust_record(claude_json, cwd) != "true":
        return "trust record absent"
    if READ.instance_dir(home, TRUSTED).exists():
        return "name not fresh"
    return None


def names_only(fields):
    """The child start line's strip fields hold names alone: each absent, or comma-joined env-style names."""
    return all(v is None or (isinstance(v, str) and STRIP_NAMES.fullmatch(v) is not None)
               for v in (fields.get("env_stripped_known"), fields.get("env_kept")))


def trusted_session(home, priv, claude, env, cwd, extra, receipt, rehearse, sub, arm=""):
    """One wrapped start of `trusted`: no key until the screen model reads the input box (a dialog or modal standing →
    no key, `modal-standing`); lines 1–2; the strip fields; the `x` and its own `human` wheel line; the DEL; the release
    and `driver`; then the wrapper SIGKILLed and the child gone. No send, no hold. Returns (codes, green)."""
    codes = {}
    human = lambda e: (e.get("data") or {}).get("holder") == "human"
    argv = [str(VIOLA), "--home", str(home), "run", TRUSTED, "--", str(claude), *extra]
    sess = Session(argv, env, cwd)
    try:
        # (1) no key before the input box reads
        end = time.monotonic() + 120
        while time.monotonic() < end and sess.exit is None:
            sess.pump(0.5)
            seen = READ.found(sess.screen.lines(), "trust-seen")
            if seen != "none":
                sess.pump(1.0)
                break
        sess.frame("trust-seen")
        codes["found"] = READ.found(sess.screen.lines(), "trust-seen")
        codes["keys_before_box"] = len(sess.written)
        if codes["found"] != "input-box":
            codes["modal"] = "modal-standing"
        else:
            # (2) the instance's own first two lines, the child's start line
            codes["session_start"] = await_kind(home, "session-start", 120, sess=sess, name=TRUSTED) is not None
            sess.pump(2.0)
            sess.frame("start")
            ev = events(home, TRUSTED)
            codes["lines_1_2"] = (len(ev) >= 2 and ev[0].get("kind") == "wheel"
                                  and (ev[0].get("data") or {}).get("cause") == "start"
                                  and ev[1].get("kind") == "session-start")
            codes["budget_kind_lines"] = sum(1 for e in ev if "budget" in str(e.get("kind")))
            child = [l for l in READ.run_log(home, TRUSTED)
                     if l.get("event") == "process-start" and (l.get("fields") or l).get("subject") == "claude-child"]
            codes["child_process_start"] = len(child)
            codes["strip_names_only"] = len(child) == 1 and names_only(child[0].get("fields") or child[0])
            # the dummy probe in the start's environment (step 3, revision 9): its name in the log, its value never
            log_text = "".join(p.read_text(encoding="utf-8", errors="replace")
                               for p in pathlib.Path(home).rglob(f"run-{TRUSTED}.ndjson"))
            codes["probe_name_logged"] = STRIP_PROBE[0] in log_text
            codes["probe_value_logged"] = STRIP_PROBE[1] in log_text
            # (3) the `x`: its own wheel line the file's first `human` line; then the DEL
            before = len(ev)
            codes["human_before_x"] = any(e.get("kind") == "wheel" and human(e) for e in ev)
            codes["keys_before_x"] = len(sess.written)
            sess.write(b"x", "input-box")
            took = await_kind(home, "wheel", 2, human, sess=sess, after=before, name=TRUSTED)
            sess.pump(0.5)
            sess.frame("after-x")
            codes["echo"] = ("78" in receipt_keys(receipt)) if rehearse else (sess.screen.box_input() == "x")
            ev = events(home, TRUSTED)
            first_human = next((i for i, e in enumerate(ev) if e.get("kind") == "wheel" and human(e)), None)
            codes["x_wheel_human"] = took is not None and first_human is not None and first_human >= before
            sess.write(b"\x7f", "input-box")
            sess.pump(1.0)
            sess.frame("after-del")
            codes["box"] = box_reading(sess.screen)
            # (4) the release, no send and no hold
            before = len(events(home, TRUSTED))
            code, _, _ = viola(home, "release", TRUSTED, env=env, timeout=30)
            codes["release"] = code
            codes["driver"] = await_kind(home, "wheel", 5, lambda e: (e.get("data") or {}).get("holder") == "driver",
                                         sess=sess, after=before, name=TRUSTED) is not None
        codes["keys"] = "+".join(sess.written) or "none"
        # (5) the wrapper ended as entry 12 ended it
        sess.frame("before-kill")
        snap = READ.snapshot(home, TRUSTED)
        wrapper_pid, child_pid = snap.get("pid"), snap.get("child_pid")
        wrapper_started = READ.start_time(wrapper_pid) if wrapper_pid else None
        child_started = READ.start_time(child_pid) if child_pid else None
        if wrapper_started is not None and child_started is not None:
            os.kill(wrapper_pid, signal.SIGKILL)
            end = time.monotonic() + 10
            while READ.alive(child_pid, child_started) and time.monotonic() < end:
                sess.pump(0.1)
            codes["child_gone_after_kill"] = not READ.alive(child_pid, child_started)
        else:
            codes["child_gone_after_kill"] = False
        sess.pump(1.0)
        sess.kill()
        sess.frame("final")
        codes["unable_bytes"] = sess.literals[b"unable: "]
        codes["hint_bytes"] = sess.literals[b"hint: "]
        codes["screens"] = save_screens(sess, sub, priv, rehearse, arm)
        green = bool(codes["found"] == "input-box" and codes["keys_before_box"] == 0 and codes.get("session_start")
                     and codes.get("lines_1_2") and codes.get("budget_kind_lines") == 0
                     and codes.get("strip_names_only") and codes.get("probe_name_logged")
                     and codes.get("probe_value_logged") is False and not codes.get("human_before_x")
                     and codes.get("keys_before_x") == 0 and codes.get("echo") and codes.get("x_wheel_human")
                     and codes.get("release") == 0 and codes.get("driver") and codes["keys"] == "input-box+input-box"
                     and codes["child_gone_after_kill"] and codes["unable_bytes"] == 0 and codes["hint_bytes"] == 0
                     and ",clean=True," in codes["screens"] and ",closed=True" in codes["screens"])
        return codes, green
    finally:
        if sess.exit is None:
            sess.kill()


def bounded(seconds):
    """A kill deadline over the whole start: SIGALRM raises, and the callers' `finally` ends what they started."""
    def fire(signum, frame):
        raise TimeoutError("kill deadline")
    signal.signal(signal.SIGALRM, fire)
    signal.alarm(seconds)


def live_trusted():
    sub = "live-trusted"
    words = words_or_refuse(("cap", "cli", "input-box"), 1)
    if words["input-box"] != "yes":
        print("refused: word input-box not yes")
        return 3
    state = READ.read_json(READ.STATE) or {}
    v = state.get("verify") or {}
    if not (v.get("stamp") == "pass" and v.get("cli") == words["cli"] and v.get("home") and v.get("base")):
        print("refused: no green live-verify for this cli")
        return 3
    base, home = ROOT / v["base"], ROOT / v["home"]
    priv, cwd = base / "priv", base / TRUSTED_CWD
    refusal = trusted_preflight(home, cwd, CLAUDE_JSON)
    if refusal:
        print(f"refused: {refusal}")
        return 3
    bin_dir = cli_dir(words["cli"])
    claude = bin_dir / "claude"
    env = {**env_for(bin_dir), STRIP_PROBE[0]: STRIP_PROBE[1]}
    codes = {"trust_record": "true", "latest": words["latest"], "viola_sha": sha16(VIOLA), "probe": STRIP_PROBE[0]}
    ledger(priv, {"kind": "start", "step": sub, "starts": 1, "live": True, "cli": words["cli"],
                  "latest": words["latest"]})
    bounded(TRUSTED_BOUND_S)
    try:
        got, green = trusted_session(home, priv, claude, env, cwd, [], priv / "receipt-trusted.ndjson", False, sub)
        codes.update(got)
    except TimeoutError:
        codes["deadline"] = TRUSTED_BOUND_S
        green = False
    finally:
        signal.alarm(0)
    codes["census_held"] = READ.census(base)
    green = green and codes["census_held"] == 0
    ledger(priv, {"kind": "reading", "mode": "live", "step": sub, "verdict": "green" if green else "red", **codes})
    return close(sub, green, codes)


def write_record(path, cwd, value):
    projects = {} if value is None else {os.path.realpath(cwd): {"hasTrustDialogAccepted": value}}
    write_private(path, json.dumps({"projects": projects}).encode())


def rehearse_trusted():
    """Step 3g (c), no start: the granted arm under the fake agent (its cwd trusted, no dialog drawn), the refusing
    arms (record absent, record `false`, name not fresh), and the modal arm (entry 24's stub draws the trust literal:
    no key, red), through the live arm's preflight and session."""
    sub = "rehearse-trusted"
    codes = {}
    base = private_dir(E2E / f"viola-live-rehearsal-{stamp()}")
    bounded(2 * TRUSTED_BOUND_S)
    try:
        home, priv = private_dir(base / "home"), private_dir(base / "priv")
        bin_dir = private_dir(priv / "bin")
        claude = bin_dir / "claude"
        shutil.copy2(FAKE, claude)
        os.chmod(claude, 0o700)
        env = env_for(bin_dir)
        if not stamp_rehearsal_home(home, claude, env):
            return close(sub, False, {"rehearsal_stamp": "red"})
        write_private(home / "config.json", json.dumps({"v": 1, "dialog_hold_s": 60}).encode())
        cwd = fresh_proj(base)
        subprocess.run(["/usr/bin/git", "init", "-q"], cwd=cwd, timeout=30, check=True,
                       stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        record = priv / "claude.json"
        codes["viola_sha"] = sha16(VIOLA)
        # the refusing arms: nothing started, no instance made
        write_record(record, cwd, None)
        codes["absent_arm"] = trusted_preflight(home, cwd, record)
        write_record(record, cwd, False)
        codes["false_arm"] = trusted_preflight(home, cwd, record)
        codes["refused_made_nothing"] = not READ.instance_dir(home, TRUSTED).exists()
        # the granted arm, a CLAUDE* name in its environment to read the strip fields against
        write_record(record, cwd, True)
        codes["granted_preflight"] = trusted_preflight(home, cwd, record) or "go"
        granted_env = {**env, STRIP_PROBE[0]: STRIP_PROBE[1]}
        receipt = priv / "receipt.ndjson"
        extra = ["--cli-version", RUN_FAKE_VERSION, "--fixtures", str(ROOT / "fixtures/claude"), "--screens",
                 "--trusted-root", str(cwd), "--receipt", str(receipt)]
        got, granted = trusted_session(home, priv, claude, granted_env, cwd, extra, receipt, True, sub, "granted")
        codes["granted"] = json.dumps(got, sort_keys=True, separators=(",", ":"))
        codes["probe_name_logged"] = got.get("probe_name_logged")
        codes["probe_value_logged"] = got.get("probe_value_logged")
        codes["names_only_controls"] = (names_only({"env_stripped_known": "CLAUDE_A,CLAUDE_B"})
                                        and not names_only({"env_kept": "CLAUDE_A=secret"}))
        # name not fresh: the granted arm's instance stands
        codes["fresh_arm"] = trusted_preflight(home, cwd, record)
        # the modal arm: entry 24's stub draws the trust literal over the wrapped session
        home2 = private_dir(base / "home-modal")
        bin2 = private_dir(priv / "bin-modal")
        stub = bin2 / "claude"
        write_private(stub, TRUST_FORM_STUB.encode())
        os.chmod(stub, 0o700)
        write_private(bin2 / "trust-form-mode", b"granted")
        cwd2 = fresh_proj(base)
        record2 = priv / "claude-modal.json"
        write_record(record2, cwd2, True)
        codes["modal_preflight"] = trusted_preflight(home2, cwd2, record2) or "go"
        got2, modal_green = trusted_session(home2, priv, stub, env_for(bin2), cwd2, [], priv / "receipt-modal.ndjson",
                                            True, sub, "modal")
        codes["modal"] = f"{got2['found']}/{got2.get('modal')}/keys={got2['keys']}/green={modal_green}"
        codes["census_held"] = READ.census(base)
        green = bool(codes["absent_arm"] == "trust record absent" and codes["false_arm"] == "trust record absent"
                     and codes["refused_made_nothing"] and codes["granted_preflight"] == "go" and granted
                     and codes["probe_name_logged"] and not codes["probe_value_logged"] and codes["names_only_controls"]
                     and codes["fresh_arm"] == "name not fresh" and codes["modal_preflight"] == "go"
                     and codes["modal"] == "trust-dialog/modal-standing/keys=none/green=False"
                     and codes["census_held"] == 0)
        return close(sub, green, codes)
    except TimeoutError:
        return close(sub, False, {**codes, "deadline": 2 * TRUSTED_BOUND_S})
    finally:
        signal.alarm(0)
        shutil.rmtree(base, ignore_errors=True)


def trust_record_read():
    """The record for entry 27's cwd, no start and no write: `trust-record: {word}` (exit 0 on `true`)."""
    state = READ.read_json(READ.STATE) or {}
    base = (state.get("verify") or {}).get("base")
    if not base:
        print("trust-record: unread — no kept base")
        return 1
    cwd = ROOT / base / TRUSTED_CWD
    if not cwd.is_dir():
        print("trust-record: unread — cwd absent")
        return 1
    word = trust_record(CLAUDE_JSON, cwd)
    print(f"trust-record: {word} — cwd {TRUSTED_CWD}")
    return 0 if word == "true" else 1


def main():
    if len(sys.argv) == 3 and sys.argv[1] == "derive-state":
        if not ((ROOT / "Cargo.toml").is_file() and (ROOT / ".andromeda").is_dir()):
            sys.exit("run from the repository root")
        return derive_state(sys.argv[2])
    if len(sys.argv) == 3 and sys.argv[1] == "stamp-check":
        if not ((ROOT / "Cargo.toml").is_file() and (ROOT / ".andromeda").is_dir()):
            sys.exit("run from the repository root")
        return stamp_check(sys.argv[2])
    verb = sys.argv[1] if len(sys.argv) == 2 else ""
    if not ((ROOT / "Cargo.toml").is_file() and (ROOT / ".andromeda").is_dir()):
        sys.exit("run from the repository root")
    table = {
        "rehearse-verify": lambda: verify(True), "live-verify": lambda: verify(False),
        "rehearse-wrapped": lambda: wrapped(True), "live-wrapped": lambda: wrapped(False),
        "rehearse-unwrapped": lambda: unwrapped(True), "live-unwrapped": lambda: unwrapped(False),
        "rehearse-derive": rehearse_derive, "rehearse-reuse": rehearse_reuse,
        "rehearse-trust-form": rehearse_trust_form,
        "rehearse-trusted": rehearse_trusted, "live-trusted": live_trusted, "trust-record": trust_record_read,
    }
    if verb not in table:
        sys.exit(__doc__)
    return table[verb]()


if __name__ == "__main__":
    sys.exit(main())

